    { r = {"LEONATO"}, t = "I learn in this letter that Don Pedro of Arragon comes this night to Messina." },
    { r = {"MESSENGER"}, t = "He is very near by this: he was not three leagues off when I left him." },
    { r = {"LEONATO"}, t = "How many gentlemen have you lost in this action?" },
