    { r = {"LEONATO"}, t = "A victory is twice itself when the achiever brings home full numbers." },
    { r = {"LEONATO"}, t = "I find here that Don Pedro hath bestowed much honour on a young Florentine called Claudio." },
    { r = {"MESSENGER"}, t = "Much deserved on his part, and equally remembered by Don Pedro." },
    { r = {"MESSENGER"}, t = "He hath borne himself beyond the promise of his age, doing in the figure of a lamb the feats of a lion: he hath indeed better bettered expectation than you must expect of me to tell you how." },
    { r = {"LEONATO"}, t = "He hath an uncle here in Messina will be very much glad of it." },
    { r = {"MESSENGER"}, t = "I have already delivered him letters, and there appears much joy in him; even so much that joy could not show itself modest enough without a badge of bitterness." },
    { r = {"LEONATO"}, t = "Did he break out into tears?" },
    { r = {"MESSENGER"}, t = "In great measure." },
    { r = {"LEONATO"}, t = "A kind overflow of kindness." },
    { r = {"LEONATO"}, t = "There are no faces truer than those that are so washed; how much better is it to weep at joy than to joy at weeping!" },
    { r = {"BEATRICE"}, t = "I pray you, is Signior Mountanto returned from the wars or no?" },
