    { r = {"LEONATO"}, t = "What is he that you ask for, niece?" },
    { r = {"HERO"}, t = "My cousin means Signior Benedick of Padua." },
    { r = {"MESSENGER"}, t = "O! he is returned, and as pleasant as ever he was." },
    { r = {"BEATRICE"}, t = "He set up his bills here in Messina and challenged Cupid at the flight; and my uncle’s fool, reading the challenge, subscribed for Cupid, and challenged him at the bird-bolt." },
    { r = {"BEATRICE"}, t = "I pray you, how many hath he killed and eaten in these wars?" },
    { r = {"BEATRICE"}, t = "But how many hath he killed? for, indeed, I promised to eat all of his killing." },
    { r = {"LEONATO"}, t = "Faith, niece, you tax Signior Benedick too much; but he’ll be meet with you, I doubt it not." },
    { r = {"MESSENGER"}, t = "He hath done good service, lady, in these wars." },
    { r = {"BEATRICE"}, t = "You had musty victual, and he hath holp to eat it; he is a very valiant trencher-man; he hath an excellent stomach." },
    { r = {"MESSENGER"}, t = "And a good soldier too, lady." },
    { r = {"BEATRICE"}, t = "And a good soldier to a lady; but what is he to a lord?" },
    { r = {"MESSENGER"}, t = "A lord to a lord, a man to a man; stuffed with all honourable virtues." },
    { r = {"BEATRICE"}, t = "It is so indeed; he is no less than a stuffed man; but for the stuffing,—well, we are all mortal." },
    { r = {"LEONATO"}, t = "You must not, sir, mistake my niece." },
    { r = {"LEONATO"}, t = "There is a kind of merry war betwixt Signior Benedick and her; they never meet but there’s a skirmish of wit between them." },
    { r = {"BEATRICE"}, t = "Alas! he gets nothing by that." },
    { r = {"BEATRICE"}, t = "In our last conflict four of his five wits went halting off, and now is the whole man governed with one!" },
    { r = {"BEATRICE"}, t = "so that if he have wit enough to keep himself warm, let him bear it for a difference between himself and his horse; for it is all the wealth that he hath left to be known a reasonable creature." },
    { r = {"BEATRICE"}, t = "Who is his companion now?" },
    { r = {"BEATRICE"}, t = "He hath every month a new sworn brother." },
    { r = {"MESSENGER"}, t = "Is’t possible?" },
    { r = {"BEATRICE"}, t = "Very easily possible: he wears his faith but as the fashion of his hat; it ever changes with the next block." },
    { r = {"MESSENGER"}, t = "I see, lady, the gentleman is not in your books." },
    { r = {"BEATRICE"}, t = "No; and he were, I would burn my study." },
    { r = {"BEATRICE"}, t = "But I pray you, who is his companion?" },
    { r = {"BEATRICE"}, t = "Is there no young squarer now that will make a voyage with him to the devil?" },
    { r = {"MESSENGER"}, t = "He is most in the company of the right noble Claudio." },
    { r = {"BEATRICE"}, t = "O Lord, he will hang upon him like a disease: he is sooner caught than the pestilence, and the taker runs presently mad." },
    { r = {"BEATRICE"}, t = "God help the noble Claudio!" },
    { r = {"BEATRICE"}, t = "If he have caught the Benedick, it will cost him a thousand pound ere he be cured." },
    { r = {"MESSENGER"}, t = "I will hold friends with you, lady." },
    { r = {"BEATRICE"}, t = "Do, good friend." },
    { r = {"LEONATO"}, t = "You will never run mad, niece." },
    { r = {"BEATRICE"}, t = "No, not till a hot January." },
    { r = {"MESSENGER"}, t = "Don Pedro is approached." },
    { d = "Enter Don Pedro, Don John, Claudio, Benedick, Balthasar and Others" },
    { r = {"DON PEDRO"}, t = "Good Signior Leonato, you are come to meet your trouble: the fashion of the world is to avoid cost, and you encounter it." },
    { r = {"LEONATO"}, t = "Never came trouble to my house in the likeness of your Grace, for trouble being gone, comfort should remain; but when you depart from me, sorrow abides and happiness takes his leave." },
    { r = {"DON PEDRO"}, t = "You embrace your charge too willingly." },
    { r = {"DON PEDRO"}, t = "I think this is your daughter." },
    { r = {"LEONATO"}, t = "Her mother hath many times told me so." },
    { r = {"BENEDICK"}, t = "Were you in doubt, sir, that you asked her?" },
    { r = {"LEONATO"}, t = "Signior Benedick, no; for then were you a child." },
    { r = {"DON PEDRO"}, t = "You have it full, Benedick: we may guess by this what you are, being a man." },
    { r = {"DON PEDRO"}, t = "Truly the lady fathers herself." },
    { r = {"DON PEDRO"}, t = "Be happy, lady, for you are like an honourable father." },
    { r = {"BENEDICK"}, t = "If Signior Leonato be her father, she would not have his head on her shoulders for all Messina, as like him as she is." },
    { r = {"BEATRICE"}, t = "I wonder that you will still be talking, Signior Benedick: nobody marks you.", e = "/sigh", at = "BENEDICK" },
    { r = {"BENEDICK"}, t = "What! my dear Lady Disdain, are you yet living?", e = "/bow", at = "BEATRICE" },
    { r = {"BEATRICE"}, t = "Is it possible Disdain should die while she hath such meet food to feed it as Signior Benedick?" },
    { r = {"BEATRICE"}, t = "Courtesy itself must convert to disdain if you come in her presence." },
    { r = {"BENEDICK"}, t = "Then is courtesy a turncoat." },
    { r = {"BENEDICK"}, t = "But it is certain I am loved of all ladies, only you excepted; and I would I could find in my heart that I had not a hard heart; for, truly, I love none." },
    { r = {"BEATRICE"}, t = "A dear happiness to women: they would else have been troubled with a pernicious suitor." },
    { r = {"BEATRICE"}, t = "I thank God and my cold blood, I am of your humour for that." },
    { r = {"BEATRICE"}, t = "I had rather hear my dog bark at a crow than a man swear he loves me." },
    { r = {"BENEDICK"}, t = "God keep your Ladyship still in that mind; so some gentleman or other shall scape a predestinate scratched face." },
    { r = {"BEATRICE"}, t = "Scratching could not make it worse, and ’twere such a face as yours were." },
    { r = {"BENEDICK"}, t = "Well, you are a rare parrot-teacher." },
    { r = {"BEATRICE"}, t = "A bird of my tongue is better than a beast of yours." },
    { r = {"BENEDICK"}, t = "I would my horse had the speed of your tongue, and so good a continuer." },
    { r = {"BENEDICK"}, t = "But keep your way, i’ God’s name; I have done." },
    { r = {"BEATRICE"}, t = "You always end with a jade’s trick: I know you of old." },
    { r = {"DON PEDRO"}, t = "That is the sum of all, Leonato: Signior Claudio, and Signior" },
    { r = {"DON PEDRO"}, t = "Benedick, my dear friend Leonato hath invited you all." },
    { r = {"DON PEDRO"}, t = "I tell him we shall stay here at the least a month, and he heartly prays some occasion may detain us longer: I dare swear he is no hypocrite, but prays from his heart." },
    { r = {"LEONATO"}, t = "If you swear, my lord, you shall not be forsworn." },
    { r = {"LEONATO"}, t = "Let me bid you welcome, my lord: being reconciled to the Prince your brother, I owe you all duty.", d = "To Don John" },
    { r = {"DON JOHN"}, t = "I thank you: I am not of many words, but I thank you." },
    { r = {"LEONATO"}, t = "Please it your Grace lead on?" },
    { r = {"DON PEDRO"}, t = "Your hand, Leonato; we will go together." },
    { d = "Exeunt all but Benedick and Claudio" },
    { r = {"CLAUDIO"}, t = "Benedick, didst thou note the daughter of Signior Leonato?" },
    { r = {"BENEDICK"}, t = "I noted her not; but I looked on her." },
    { r = {"CLAUDIO"}, t = "Is she not a modest young lady?" },
    { r = {"BENEDICK"}, t = "Do you question me, as an honest man should do, for my simple true judgment; or would you have me speak after my custom, as being a professed tyrant to their sex?" },
    { r = {"CLAUDIO"}, t = "No; I pray thee speak in sober judgment." },
    { r = {"BENEDICK"}, t = "Why, i’ faith, methinks she’s too low for a high praise, too brown for a fair praise, and too little for a great praise;" },
    { r = {"BENEDICK"}, t = "only this commendation I can afford her, that were she other than she is, she were unhandsome, and being no other but as she is, I do not like her." },
    { r = {"CLAUDIO"}, t = "Thou thinkest I am in sport: I pray thee tell me truly how thou likest her." },
    { r = {"BENEDICK"}, t = "Would you buy her, that you enquire after her?" },
    { r = {"CLAUDIO"}, t = "Can the world buy such a jewel?" },
    { r = {"BENEDICK"}, t = "Yea, and a case to put it into." },
    { r = {"BENEDICK"}, t = "But speak you this with a sad brow, or do you play the flouting Jack, to tell us Cupid is a good hare-finder, and Vulcan a rare carpenter?" },
    { r = {"BENEDICK"}, t = "Come, in what key shall a man take you, to go in the song?" },
    { r = {"CLAUDIO"}, t = "In mine eye she is the sweetest lady that ever I looked on." },
    { r = {"BENEDICK"}, t = "I can see yet without spectacles and I see no such matter: there’s her cousin and she were not possessed with a fury, exceeds her as much in beauty as the first of May doth the last of December." },
    { r = {"BENEDICK"}, t = "But I hope you have no intent to turn husband, have you?" },
    { r = {"CLAUDIO"}, t = "I would scarce trust myself, though I had sworn to the contrary, if Hero would be my wife." },
    { r = {"BENEDICK"}, t = "Is’t come to this, in faith?" },
    { r = {"BENEDICK"}, t = "Hath not the world one man but he will wear his cap with suspicion?" },
    { r = {"BENEDICK"}, t = "Shall I never see a bachelor of threescore again?" },
    { r = {"BENEDICK"}, t = "Go to, i’ faith; and thou wilt needs thrust thy neck into a yoke, wear the print of it and sigh away Sundays." },
    { d = "Re-enter Don Pedro" },
    { r = {"BENEDICK"}, t = "Look! Don Pedro is returned to seek you." },
    { r = {"DON PEDRO"}, t = "What secret hath held you here, that you followed not to" },
    { r = {"DON PEDRO"}, t = "Leonato’s?" },
    { r = {"BENEDICK"}, t = "I would your Grace would constrain me to tell." },
    { r = {"DON PEDRO"}, t = "I charge thee on thy allegiance." },
    { r = {"BENEDICK"}, t = "You hear, Count Claudio: I can be secret as a dumb man; I would have you think so; but on my allegiance mark you this, on my allegiance: he is in love." },
    { r = {"BENEDICK"}, t = "With who? now that is your Grace’s part." },
    { r = {"BENEDICK"}, t = "Mark how short his answer is: with Hero, Leonato’s short daughter." },
    { r = {"CLAUDIO"}, t = "If this were so, so were it uttered." },
    { r = {"BENEDICK"}, t = "Like the old tale, my lord: ‘it is not so, nor ’twas not so; but indeed, God forbid it should be so.’" },
    { r = {"CLAUDIO"}, t = "If my passion change not shortly, God forbid it should be otherwise." },
    { r = {"DON PEDRO"}, t = "Amen, if you love her; for the lady is very well worthy." },
    { r = {"CLAUDIO"}, t = "You speak this to fetch me in, my lord." },
    { r = {"DON PEDRO"}, t = "By my troth, I speak my thought." },
    { r = {"CLAUDIO"}, t = "And in faith, my lord, I spoke mine." },
    { r = {"BENEDICK"}, t = "And by my two faiths and troths, my lord, I spoke mine." },
    { r = {"CLAUDIO"}, t = "That I love her, I feel." },
    { r = {"DON PEDRO"}, t = "That she is worthy, I know." },
    { r = {"BENEDICK"}, t = "That I neither feel how she should be loved, nor know how she should be worthy, is the opinion that fire cannot melt out of me: I will die in it at the stake." },
    { r = {"DON PEDRO"}, t = "Thou wast ever an obstinate heretic in the despite of beauty." },
    { r = {"CLAUDIO"}, t = "And never could maintain his part but in the force of his will." },
    { r = {"BENEDICK"}, t = "That a woman conceived me, I thank her; that she brought me up, I likewise give her most humble thanks; but that I will have a recheat winded in my forehead, or hang my bugle in an invisible baldrick, all women shall pardon me." },
    { r = {"BENEDICK"}, t = "Because I will not do them the wrong to mistrust any, I will do myself the right to trust none; and the fine is,—for the which I may go the finer,—I will live a bachelor." },
    { r = {"DON PEDRO"}, t = "I shall see thee, ere I die, look pale with love." },
    { r = {"BENEDICK"}, t = "With anger, with sickness, or with hunger, my lord; not with love:" },
    { r = {"BENEDICK"}, t = "prove that ever I lose more blood with love than I will get again with drinking, pick out mine eyes with a ballad-maker’s pen and hang me up at the door of a brothel-house for the sign of blind Cupid." },
    { r = {"DON PEDRO"}, t = "Well, if ever thou dost fall from this faith, thou wilt prove a notable argument." },
    { r = {"BENEDICK"}, t = "If I do, hang me in a bottle like a cat and shoot at me; and he that hits me, let him be clapped on the shoulder and called Adam." },
    { r = {"DON PEDRO"}, t = "Well, as time shall try: ‘In time the savage bull doth bear the yoke.’" },
    { r = {"BENEDICK"}, t = "The savage bull may; but if ever the sensible Benedick bear it, pluck off the bull’s horns and set them in my forehead;" },
    { r = {"BENEDICK"}, t = "and let me be vilely painted, and in such great letters as they write, ‘Here is good horse to hire,’ let them signify under my sign ‘Here you may see Benedick the married man.’" },
    { r = {"CLAUDIO"}, t = "If this should ever happen, thou wouldst be horn-mad." },
    { r = {"DON PEDRO"}, t = "Nay, if Cupid have not spent all his quiver in Venice, thou wilt quake for this shortly." },
    { r = {"BENEDICK"}, t = "I look for an earthquake too then." },
    { r = {"DON PEDRO"}, t = "Well, you will temporize with the hours." },
    { r = {"DON PEDRO"}, t = "In the meantime, good Signior Benedick, repair to Leonato’s: commend me to him and tell him I will not fail him at supper; for indeed he hath made great preparation." },
    { r = {"BENEDICK"}, t = "I have almost matter enough in me for such an embassage; and so I commit you" },
    { r = {"CLAUDIO"}, t = "To the tuition of God: from my house, if I had it," },
    { r = {"DON PEDRO"}, t = "The sixth of July: your loving friend, Benedick." },
    { r = {"BENEDICK"}, t = "Nay, mock not, mock not." },
    { r = {"BENEDICK"}, t = "The body of your discourse is sometime guarded with fragments, and the guards are but slightly basted on neither: ere you flout old ends any further, examine your conscience: and so I leave you." },
    { d = "Exit" },
    { r = {"CLAUDIO"}, t = "My liege, your Highness now may do me good." },
    { r = {"DON PEDRO"}, t = "My love is thine to teach: teach it but how," },
    { r = {"DON PEDRO"}, t = "And thou shalt see how apt it is to learn" },
    { r = {"DON PEDRO"}, t = "Any hard lesson that may do thee good." },
    { r = {"CLAUDIO"}, t = "Hath Leonato any son, my lord?" },
    { r = {"DON PEDRO"}, t = "No child but Hero; she’s his only heir." },
    { r = {"DON PEDRO"}, t = "Dost thou affect her, Claudio?" },
    { r = {"CLAUDIO"}, t = "O! my lord," },
    { r = {"CLAUDIO"}, t = "When you went onward on this ended action," },
    { r = {"CLAUDIO"}, t = "I looked upon her with a soldier’s eye," },
    { r = {"CLAUDIO"}, t = "That lik’d, but had a rougher task in hand" },
    { r = {"CLAUDIO"}, t = "Than to drive liking to the name of love;" },
    { r = {"CLAUDIO"}, t = "But now I am return’d, and that war-thoughts" },
    { r = {"CLAUDIO"}, t = "Have left their places vacant, in their rooms" },
    { r = {"CLAUDIO"}, t = "Come thronging soft and delicate desires," },
    { r = {"CLAUDIO"}, t = "All prompting me how fair young Hero is," },
    { r = {"CLAUDIO"}, t = "Saying, I lik’d her ere I went to wars." },
    { r = {"DON PEDRO"}, t = "Thou wilt be like a lover presently," },
    { r = {"DON PEDRO"}, t = "And tire the hearer with a book of words." },
    { r = {"DON PEDRO"}, t = "If thou dost love fair Hero, cherish it," },
    { r = {"DON PEDRO"}, t = "And I will break with her, and with her father," },
    { r = {"DON PEDRO"}, t = "And thou shalt have her. Was’t not to this end" },
    { r = {"DON PEDRO"}, t = "That thou began’st to twist so fine a story?" },
    { r = {"CLAUDIO"}, t = "How sweetly you do minister to love," },
    { r = {"CLAUDIO"}, t = "That know love’s grief by his complexion!" },
    { r = {"CLAUDIO"}, t = "But lest my liking might too sudden seem," },
    { r = {"CLAUDIO"}, t = "I would have salv’d it with a longer treatise." },
    { r = {"DON PEDRO"}, t = "What need the bridge much broader than the flood?" },
    { r = {"DON PEDRO"}, t = "The fairest grant is the necessity." },
    { r = {"DON PEDRO"}, t = "Look, what will serve is fit: ’tis once, thou lov’st," },
    { r = {"DON PEDRO"}, t = "And I will fit thee with the remedy." },
    { r = {"DON PEDRO"}, t = "I know we shall have revelling tonight:" },
    { r = {"DON PEDRO"}, t = "I will assume thy part in some disguise," },
    { r = {"DON PEDRO"}, t = "And tell fair Hero I am Claudio;" },
    { r = {"DON PEDRO"}, t = "And in her bosom I’ll unclasp my heart," },
    { r = {"DON PEDRO"}, t = "And take her hearing prisoner with the force" },
    { r = {"DON PEDRO"}, t = "And strong encounter of my amorous tale:" },
    { r = {"DON PEDRO"}, t = "Then after to her father will I break;" },
    { r = {"DON PEDRO"}, t = "And the conclusion is, she shall be thine." },
    { r = {"DON PEDRO"}, t = "In practice let us put it presently." },
