    { d = "Act 1, Scene 2. A room in Leonato’s house.", h = true },
    { d = "Enter Leonato and Antonio, meeting" },
    { r = {"LEONATO"}, t = "How now, brother?" },
    { r = {"LEONATO"}, t = "Where is my cousin your son?" },
    { r = {"LEONATO"}, t = "Hath he provided this music?" },
    { r = {"ANTONIO"}, t = "He is very busy about it." },
    { r = {"ANTONIO"}, t = "But, brother, I can tell you strange news that you yet dreamt not of." },
    { r = {"LEONATO"}, t = "Are they good?" },
    { r = {"ANTONIO"}, t = "As the event stamps them: but they have a good cover; they show well outward." },
    { r = {"ANTONIO"}, t = "The Prince and Count Claudio, walking in a thick-pleached alley in my orchard, were thus much overheard by a man of mine: the Prince discovered to Claudio that he loved my niece your daughter and meant to acknowledge it this night in a dance;" },
    { r = {"ANTONIO"}, t = "and if he found her accordant, he meant to take the present time by the top and instantly break with you of it." },
    { r = {"LEONATO"}, t = "Hath the fellow any wit that told you this?" },
    { r = {"ANTONIO"}, t = "A good sharp fellow: I will send for him; and question him yourself." },
    { r = {"LEONATO"}, t = "No, no; we will hold it as a dream till it appear itself: but I will acquaint my daughter withal, that she may be the better prepared for an answer, if peradventure this be true." },
    { r = {"LEONATO"}, t = "Go you and tell her of it." },
