    { r = {"LEONATO"}, t = "Cousins, you know what you have to do." },
    { r = {"LEONATO"}, t = "O!" },
    { r = {"LEONATO"}, t = "I cry you mercy, friend; go you with me, and I will use your skill." },
    { r = {"LEONATO"}, t = "Good cousin, have a care this busy time." },
    { d = "Exeunt" },
    { d = "Act 1, Scene 3. Another room in Leonato’s house.", h = true },
    { d = "Enter Don John and Conrade" },
    { r = {"CONRADE"}, t = "What the good-year, my lord! why are you thus out of measure sad?" },
    { r = {"DON JOHN"}, t = "There is no measure in the occasion that breeds; therefore the sadness is without limit." },
    { r = {"CONRADE"}, t = "You should hear reason." },
    { r = {"DON JOHN"}, t = "And when I have heard it, what blessings brings it?" },
    { r = {"CONRADE"}, t = "If not a present remedy, at least a patient sufferance." },
    { r = {"DON JOHN"}, t = "I wonder that thou (being as thou say’st thou art, born under Saturn) goest about to apply a moral medicine to a mortifying mischief." },
    { r = {"DON JOHN"}, t = "I cannot hide what I am: I must be sad when I have cause, and smile at no man’s jests; eat when I have stomach, and wait for no man’s leisure; sleep when I am drowsy, and tend on no man’s business;" },
    { r = {"DON JOHN"}, t = "laugh when I am merry, and claw no man in his humour." },
    { r = {"CONRADE"}, t = "Yea; but you must not make the full show of this till you may do it without controlment." },
    { r = {"CONRADE"}, t = "You have of late stood out against your brother, and he hath ta’en you newly into his grace; where it is impossible you should take true root but by the fair weather that you make yourself:" },
    { r = {"CONRADE"}, t = "it is needful that you frame the season for your own harvest." },
    { r = {"DON JOHN"}, t = "I had rather be a canker in a hedge than a rose in his grace; and it better fits my blood to be disdained of all than to fashion a carriage to rob love from any:" },
    { r = {"DON JOHN"}, t = "in this, though I cannot be said to be a flattering honest man, it must not be denied but I am a plain-dealing villain." },
    { r = {"DON JOHN"}, t = "I am trusted with a muzzle and enfranchised with a clog; therefore I have decreed not to sing in my cage." },
    { r = {"DON JOHN"}, t = "If I had my mouth, I would bite; if I had my liberty, I would do my liking: in the meantime, let me be that I am, and seek not to alter me." },
    { r = {"CONRADE"}, t = "Can you make no use of your discontent?" },
    { r = {"DON JOHN"}, t = "I make all use of it, for I use it only. Who comes here?" },
    { d = "Enter Borachio" },
    { r = {"DON JOHN"}, t = "What news, Borachio?" },
    { r = {"BORACHIO"}, t = "I came yonder from a great supper: the Prince your brother is royally entertained by Leonato; and I can give you intelligence of an intended marriage." },
    { r = {"DON JOHN"}, t = "Will it serve for any model to build mischief on?" },
    { r = {"DON JOHN"}, t = "What is he for a fool that betroths himself to unquietness?" },
    { r = {"BORACHIO"}, t = "Marry, it is your brother’s right hand." },
    { r = {"DON JOHN"}, t = "Who? the most exquisite Claudio?" },
    { r = {"BORACHIO"}, t = "Even he." },
    { r = {"DON JOHN"}, t = "A proper squire! And who, and who? which way looks he?" },
    { r = {"BORACHIO"}, t = "Marry, on Hero, the daughter and heir of Leonato." },
    { r = {"DON JOHN"}, t = "A very forward March-chick! How came you to this?" },
    { r = {"BORACHIO"}, t = "Being entertained for a perfumer, as I was smoking a musty room, comes me the Prince and Claudio, hand in hand, in sad conference:" },
    { r = {"BORACHIO"}, t = "I whipt me behind the arras, and there heard it agreed upon that the Prince should woo Hero for himself, and having obtained her, give her to Count Claudio." },
    { r = {"DON JOHN"}, t = "Come, come; let us thither: this may prove food to my displeasure." },
    { r = {"DON JOHN"}, t = "That young start-up hath all the glory of my overthrow: if I can cross him any way, I bless myself every way." },
    { r = {"DON JOHN"}, t = "You are both sure, and will assist me?" },
    { r = {"CONRADE"}, t = "To the death, my lord." },
    { r = {"DON JOHN"}, t = "Let us to the great supper: their cheer is the greater that I am subdued." },
    { r = {"DON JOHN"}, t = "Would the cook were of my mind!" },
    { r = {"DON JOHN"}, t = "Shall we go to prove what’s to be done?" },
    { r = {"BORACHIO"}, t = "We’ll wait upon your Lordship." },
    { d = "Exeunt" },
    { d = "Act 2, Scene 1. A hall in Leonato’s house.", h = true },
    { d = "Enter Leonato, Antonio, Hero, Beatrice and others" },
    { r = {"LEONATO"}, t = "Was not Count John here at supper?" },
    { r = {"ANTONIO"}, t = "I saw him not." },
    { r = {"BEATRICE"}, t = "How tartly that gentleman looks!" },
    { r = {"BEATRICE"}, t = "I never can see him but I am heart-burned an hour after." },
    { r = {"HERO"}, t = "He is of a very melancholy disposition." },
    { r = {"BEATRICE"}, t = "He were an excellent man that were made just in the mid-way between him and Benedick: the one is too like an image, and says nothing; and the other too like my lady’s eldest son, evermore tattling." },
    { r = {"LEONATO"}, t = "Then half Signior Benedick’s tongue in Count John’s mouth, and half Count John’s melancholy in Signior Benedick’s face" },
    { r = {"BEATRICE"}, t = "With a good leg and a good foot, uncle, and money enough in his purse, such a man would win any woman in the world if a’ could get her good will." },
    { r = {"LEONATO"}, t = "By my troth, niece, thou wilt never get thee a husband, if thou be so shrewd of thy tongue." },
    { r = {"ANTONIO"}, t = "In faith, she’s too curst." },
    { r = {"BEATRICE"}, t = "Too curst is more than curst: I shall lessen God’s sending that way; for it is said, ‘God sends a curst cow short horns;’ but to a cow too curst he sends none." },
    { r = {"LEONATO"}, t = "So, by being too curst, God will send you no horns?" },
    { r = {"BEATRICE"}, t = "Just, if he send me no husband; for the which blessing I am at him upon my knees every morning and evening." },
    { r = {"BEATRICE"}, t = "Lord!" },
    { r = {"BEATRICE"}, t = "I could not endure a husband with a beard on his face: I had rather lie in the woollen." },
    { r = {"LEONATO"}, t = "You may light on a husband that hath no beard." },
    { r = {"BEATRICE"}, t = "What should I do with him? dress him in my apparel and make him my waiting gentlewoman?" },
    { r = {"BEATRICE"}, t = "He that hath a beard is more than a youth, and he that hath no beard is less than a man; and he that is more than a youth is not for me; and he that is less than a man, I am not for him:" },
    { r = {"BEATRICE"}, t = "therefore I will even take sixpence in earnest of the bear-ward, and lead his apes into hell." },
    { r = {"LEONATO"}, t = "Well then, go you into hell?" },
    { r = {"BEATRICE"}, t = "No; but to the gate; and there will the Devil meet me, like an old cuckold, with horns on his head, and say, ‘Get you to heaven, Beatrice, get you to heaven; here’s no place for you maids.’" },
    { r = {"BEATRICE"}, t = "So deliver I up my apes, and away to Saint Peter for the heavens: he shows me where the bachelors sit, and there live we as merry as the day is long." },
    { r = {"ANTONIO"}, t = "Well, niece, I trust you will be ruled by your father.", d = "To Hero" },
    { r = {"BEATRICE"}, t = "Yes, faith; it is my cousin’s duty to make curtsy, and say, ‘Father, as it please you:’— but yet for all that, cousin, let him be a handsome fellow, or else make another curtsy, and say, ‘Father, as it please me.’" },
    { r = {"LEONATO"}, t = "Well, niece, I hope to see you one day fitted with a husband." },
    { r = {"BEATRICE"}, t = "Not till God make men of some other metal than earth." },
    { r = {"BEATRICE"}, t = "Would it not grieve a woman to be over-mastered with a piece of valiant dust? to make an account of her life to a clod of wayward marl?" },
    { r = {"BEATRICE"}, t = "No, uncle, I’ll none: Adam’s sons are my brethren; and truly, I hold it a sin to match in my kindred." },
    { r = {"LEONATO"}, t = "Daughter, remember what I told you: if the Prince do solicit you in that kind, you know your answer." },
    { r = {"BEATRICE"}, t = "The fault will be in the music, cousin, if you be not wooed in good time: if the Prince be too important, tell him there is measure in everything, and so dance out the answer." },
    { r = {"BEATRICE"}, t = "For, hear me, Hero: wooing, wedding, and repenting is as a Scotch jig, a measure, and a cinquepace: the first suit is hot and hasty, like a Scotch jig, and full as fantastical; the wedding, mannerly modest, as a measure, full of state and ancientry;" },
    { r = {"BEATRICE"}, t = "and then comes Repentance, and with his bad legs, falls into the cinquepace faster and faster, till he sink into his grave." },
    { r = {"LEONATO"}, t = "Cousin, you apprehend passing shrewdly." },
    { r = {"BEATRICE"}, t = "I have a good eye, uncle: I can see a church by daylight." },
    { r = {"LEONATO"}, t = "The revellers are entering, brother: make good room." },
    { d = "Enter Don Pedro, Claudio, Benedick, Balthasar, Don John, Borachio, Margaret, Ursula and Others, masked" },
    { r = {"DON PEDRO"}, t = "Lady, will you walk about with your friend?" },
    { r = {"HERO"}, t = "So you walk softly and look sweetly and say nothing, I am yours for the walk; and especially when I walk away." },
    { r = {"DON PEDRO"}, t = "With me in your company?" },
    { r = {"HERO"}, t = "I may say so, when I please." },
    { r = {"DON PEDRO"}, t = "And when please you to say so?" },
    { r = {"HERO"}, t = "When I like your favour; for God defend the lute should be like the case!" },
    { r = {"DON PEDRO"}, t = "My visor is Philemon’s roof; within the house is Jove." },
    { r = {"HERO"}, t = "Why, then, your visor should be thatch’d." },
    { r = {"DON PEDRO"}, t = "Speak low, if you speak love." },
    { d = "Takes her aside" },
    { r = {"BALTHASAR"}, t = "Well, I would you did like me." },
    { r = {"MARGARET"}, t = "So would not I, for your own sake; for I have many ill qualities." },
    { r = {"BALTHASAR"}, t = "Which is one?" },
    { r = {"MARGARET"}, t = "I say my prayers aloud." },
    { r = {"BALTHASAR"}, t = "I love you the better; the hearers may cry Amen." },
    { r = {"MARGARET"}, t = "God match me with a good dancer!" },
    { r = {"BALTHASAR"}, t = "Amen." },
    { r = {"MARGARET"}, t = "And God keep him out of my sight when the dance is done! Answer, clerk." },
    { r = {"BALTHASAR"}, t = "No more words: the clerk is answered." },
    { r = {"URSULA"}, t = "I know you well enough: you are Signior Antonio." },
    { r = {"ANTONIO"}, t = "At a word, I am not." },
    { r = {"URSULA"}, t = "I know you by the waggling of your head." },
    { r = {"ANTONIO"}, t = "To tell you true, I counterfeit him." },
    { r = {"URSULA"}, t = "You could never do him so ill-well, unless you were the very man." },
    { r = {"URSULA"}, t = "Here’s his dry hand up and down: you are he, you are he." },
    { r = {"ANTONIO"}, t = "At a word, I am not." },
    { r = {"URSULA"}, t = "Come, come; do you think I do not know you by your excellent wit?" },
    { r = {"URSULA"}, t = "Can virtue hide itself?" },
    { r = {"URSULA"}, t = "Go to, mum, you are he: graces will appear, and there’s an end." },
    { r = {"BEATRICE"}, t = "Will you not tell me who told you so?" },
    { r = {"BENEDICK"}, t = "No, you shall pardon me." },
    { r = {"BEATRICE"}, t = "Nor will you not tell me who you are?" },
    { r = {"BENEDICK"}, t = "Not now." },
    { r = {"BEATRICE"}, t = "That I was disdainful, and that I had my good wit out of the ‘Hundred Merry Tales.’" },
    { r = {"BEATRICE"}, t = "Well, this was Signior" },
    { r = {"BEATRICE"}, t = "Benedick that said so." },
    { r = {"BENEDICK"}, t = "What’s he?" },
    { r = {"BEATRICE"}, t = "I am sure you know him well enough." },
    { r = {"BENEDICK"}, t = "Not I, believe me." },
    { r = {"BEATRICE"}, t = "Did he never make you laugh?" },
    { r = {"BENEDICK"}, t = "I pray you, what is he?" },
    { r = {"BEATRICE"}, t = "Why, he is the Prince’s jester: a very dull fool; only his gift is in devising impossible slanders: none but libertines delight in him; and the commendation is not in his wit, but in his villainy;" },
    { r = {"BEATRICE"}, t = "for he both pleases men and angers them, and then they laugh at him and beat him." },
    { r = {"BEATRICE"}, t = "I am sure he is in the fleet: I would he had boarded me!" },
    { r = {"BENEDICK"}, t = "When I know the gentleman, I’ll tell him what you say." },
    { r = {"BEATRICE"}, t = "Do, do: he’ll but break a comparison or two on me; which, peradventure not marked or not laughed at, strikes him into melancholy; and then there’s a partridge wing saved, for the fool will eat no supper that night." },
    { r = {"BEATRICE"}, t = "We must follow the leaders.", d = "Music within" },
    { r = {"BENEDICK"}, t = "In every good thing." },
    { r = {"BEATRICE"}, t = "Nay, if they lead to any ill, I will leave them at the next turning." },
    { d = "Dance. Then exeunt all but Don John, Borachio and Claudio" },
    { r = {"DON JOHN"}, t = "Sure my brother is amorous on Hero, and hath withdrawn her father to break with him about it." },
    { r = {"DON JOHN"}, t = "The ladies follow her and but one visor remains." },
    { r = {"BORACHIO"}, t = "And that is Claudio: I know him by his bearing." },
    { r = {"DON JOHN"}, t = "Are you not Signior Benedick?" },
    { r = {"CLAUDIO"}, t = "You know me well; I am he." },
    { r = {"DON JOHN"}, t = "Signior, you are very near my brother in his love: he is enamoured on Hero; I pray you, dissuade him from her; she is no equal for his birth: you may do the part of an honest man in it." },
    { r = {"CLAUDIO"}, t = "How know you he loves her?" },
    { r = {"DON JOHN"}, t = "I heard him swear his affection." },
    { r = {"BORACHIO"}, t = "So did I too; and he swore he would marry her tonight." },
    { r = {"DON JOHN"}, t = "Come, let us to the banquet." },
    { d = "Exeunt Don John and Borachio" },
    { r = {"CLAUDIO"}, t = "Thus answer I in name of Benedick," },
    { r = {"CLAUDIO"}, t = "But hear these ill news with the ears of Claudio." },
    { r = {"CLAUDIO"}, t = "’Tis certain so; the Prince wooss for himself." },
    { r = {"CLAUDIO"}, t = "Friendship is constant in all other things" },
    { r = {"CLAUDIO"}, t = "Save in the office and affairs of love:" },
    { r = {"CLAUDIO"}, t = "Therefore all hearts in love use their own tongues;" },
    { r = {"CLAUDIO"}, t = "Let every eye negotiate for itself" },
    { r = {"CLAUDIO"}, t = "And trust no agent; for beauty is a witch" },
    { r = {"CLAUDIO"}, t = "Against whose charms faith melteth into blood." },
    { r = {"CLAUDIO"}, t = "This is an accident of hourly proof," },
    { r = {"CLAUDIO"}, t = "Which I mistrusted not. Farewell, therefore, Hero!" },
    { d = "Re-enter Benedick" },
    { r = {"BENEDICK"}, t = "Count Claudio?" },
    { r = {"CLAUDIO"}, t = "Yea, the same." },
    { r = {"BENEDICK"}, t = "Come, will you go with me?" },
    { r = {"CLAUDIO"}, t = "Whither?" },
    { r = {"BENEDICK"}, t = "Even to the next willow, about your own business, Count." },
    { r = {"BENEDICK"}, t = "What fashion will you wear the garland of?" },
    { r = {"BENEDICK"}, t = "About your neck, like a usurer’s chain? or under your arm, like a lieutenant’s scarf?" },
    { r = {"BENEDICK"}, t = "You must wear it one way, for the Prince hath got your Hero." },
    { r = {"CLAUDIO"}, t = "I wish him joy of her." },
    { r = {"BENEDICK"}, t = "Why, that’s spoken like an honest drovier: so they sell bullocks." },
    { r = {"BENEDICK"}, t = "But did you think the Prince would have served you thus?" },
    { r = {"CLAUDIO"}, t = "I pray you, leave me." },
    { r = {"BENEDICK"}, t = "Ho! now you strike like the blind man: ’twas the boy that stole your meat, and you’ll beat the post." },
    { r = {"CLAUDIO"}, t = "If it will not be, I’ll leave you." },
    { d = "Exit" },
    { r = {"BENEDICK"}, t = "Alas! poor hurt fowl." },
    { r = {"BENEDICK"}, t = "Now will he creep into sedges." },
    { r = {"BENEDICK"}, t = "But, that my Lady Beatrice should know me, and not know me!" },
    { r = {"BENEDICK"}, t = "The Prince’s fool!" },
    { r = {"BENEDICK"}, t = "Ha! it may be I go under that title because I am merry." },
    { r = {"BENEDICK"}, t = "Yea, but so I am apt to do myself wrong; I am not so reputed: it is the base though bitter disposition of Beatrice that puts the world into her person, and so gives me out." },
    { r = {"BENEDICK"}, t = "Well, I’ll be revenged as I may." },
    { d = "Re-enter Don Pedro" },
    { r = {"DON PEDRO"}, t = "Now, signior, where’s the Count? Did you see him?" },
    { r = {"BENEDICK"}, t = "Troth, my lord, I have played the part of Lady Fame." },
    { r = {"BENEDICK"}, t = "I found him here as melancholy as a lodge in a warren." },
    { r = {"BENEDICK"}, t = "I told him, and I think I told him true, that your Grace had got the good will of this young lady; and I offered him my company to a willow tree, either to make him a garland, as being forsaken, or to bind him up a rod, as being worthy to be whipped." },
    { r = {"DON PEDRO"}, t = "To be whipped! What’s his fault?" },
    { r = {"BENEDICK"}, t = "The flat transgression of a school-boy, who, being overjoy’d with finding a bird’s nest, shows it his companion, and he steals it." },
    { r = {"DON PEDRO"}, t = "Wilt thou make a trust a transgression? The transgression is in the stealer." },
    { r = {"BENEDICK"}, t = "Yet it had not been amiss the rod had been made, and the garland too; for the garland he might have worn himself, and the rod he might have bestowed on you, who, as I take it, have stolen his bird’s nest." },
    { r = {"DON PEDRO"}, t = "I will but teach them to sing, and restore them to the owner." },
    { r = {"BENEDICK"}, t = "If their singing answer your saying, by my faith, you say honestly." },
    { r = {"DON PEDRO"}, t = "The Lady Beatrice hath a quarrel to you: the gentleman that danced with her told her she is much wronged by you." },
    { r = {"BENEDICK"}, t = "O! she misused me past the endurance of a block: an oak but with one green leaf on it would have answered her: my very visor began to assume life and scold with her." },
    { r = {"BENEDICK"}, t = "She told me, not thinking I had been myself, that I was the Prince’s jester, that I was duller than a great thaw; huddling jest upon jest with such impossible conveyance upon me, that I stood like a man at a mark, with a whole army shooting at me." },
    { r = {"BENEDICK"}, t = "She speaks poniards, and every word stabs: if her breath were as terrible as her terminations, there were no living near her; she would infect to the north star." },
    { r = {"BENEDICK"}, t = "I would not marry her, though she were endowed with all that Adam had left him before he transgressed: she would have made Hercules have turned spit, yea, and have cleft his club to make the fire too." },
    { r = {"BENEDICK"}, t = "Come, talk not of her; you shall find her the infernal Ate in good apparel." },
    { r = {"BENEDICK"}, t = "I would to God some scholar would conjure her, for certainly, while she is here, a man may live as quiet in hell as in a sanctuary; and people sin upon purpose because they would go thither;" },
    { r = {"BENEDICK"}, t = "so indeed, all disquiet, horror and perturbation follow her." },
    { d = "Re-enter Claudio, Beatrice, Hero and Leonato" },
    { r = {"DON PEDRO"}, t = "Look! here she comes." },
    { r = {"BENEDICK"}, t = "Will your Grace command me any service to the world’s end?" },
    { r = {"BENEDICK"}, t = "I will go on the slightest errand now to the Antipodes that you can devise to send me on; I will fetch you a toothpicker now from the furthest inch of Asia; bring you the length of Prester John’s foot; fetch you a hair off the Great Cham’s beard;" },
    { r = {"BENEDICK"}, t = "do you any embassage to the" },
    { r = {"BENEDICK"}, t = "Pygmies, rather than hold three words’ conference with this harpy." },
    { r = {"BENEDICK"}, t = "You have no employment for me?" },
    { r = {"DON PEDRO"}, t = "None, but to desire your good company." },
    { r = {"BENEDICK"}, t = "O God, sir, here’s a dish I love not: I cannot endure my Lady Tongue." },
    { d = "Exit" },
    { r = {"DON PEDRO"}, t = "Come, lady, come; you have lost the heart of Signior Benedick." },
    { r = {"BEATRICE"}, t = "Indeed, my lord, he lent it me awhile; and I gave him use for it, a double heart for a single one: marry, once before he won it of me with false dice, therefore your Grace may well say I have lost it." },
    { r = {"DON PEDRO"}, t = "You have put him down, lady, you have put him down." },
    { r = {"BEATRICE"}, t = "So I would not he should do me, my lord, lest I should prove the mother of fools." },
    { r = {"BEATRICE"}, t = "I have brought Count Claudio, whom you sent me to seek." },
    { r = {"DON PEDRO"}, t = "Why, how now, Count! wherefore are you sad?" },
    { r = {"CLAUDIO"}, t = "Not sad, my lord." },
    { r = {"DON PEDRO"}, t = "How then? Sick?" },
    { r = {"CLAUDIO"}, t = "Neither, my lord." },
    { r = {"BEATRICE"}, t = "The Count is neither sad, nor sick, nor merry, nor well; but civil Count, civil as an orange, and something of that jealous complexion." },
    { r = {"DON PEDRO"}, t = "I’ faith, lady, I think your blazon to be true; though, I’ll be sworn, if he be so, his conceit is false." },
    { r = {"DON PEDRO"}, t = "Here, Claudio, I have wooed in thy name, and fair Hero is won; I have broke with her father, and, his good will obtained; name the day of marriage, and God give thee joy!" },
    { r = {"LEONATO"}, t = "Count, take of me my daughter, and with her my fortunes: his" },
    { r = {"LEONATO"}, t = "Grace hath made the match, and all grace say Amen to it!" },
    { r = {"BEATRICE"}, t = "Speak, Count, ’tis your cue." },
    { r = {"CLAUDIO"}, t = "Silence is the perfectest herald of joy: I were but little happy, if I could say how much." },
    { r = {"CLAUDIO"}, t = "Lady, as you are mine, I am yours: I give away myself for you and dote upon the exchange." },
    { r = {"BEATRICE"}, t = "Speak, cousin; or, if you cannot, stop his mouth with a kiss, and let not him speak neither." },
    { r = {"DON PEDRO"}, t = "In faith, lady, you have a merry heart." },
    { r = {"BEATRICE"}, t = "Yea, my lord; I thank it, poor fool, it keeps on the windy side of care." },
    { r = {"BEATRICE"}, t = "My cousin tells him in his ear that he is in her heart." },
    { r = {"CLAUDIO"}, t = "And so she doth, cousin." },
    { r = {"BEATRICE"}, t = "Good Lord, for alliance!" },
    { r = {"BEATRICE"}, t = "Thus goes everyone to the world but I, and I am sunburnt." },
    { r = {"BEATRICE"}, t = "I may sit in a corner and cry heigh-ho for a husband!" },
    { r = {"DON PEDRO"}, t = "Lady Beatrice, I will get you one." },
    { r = {"BEATRICE"}, t = "I would rather have one of your father’s getting." },
    { r = {"BEATRICE"}, t = "Hath your Grace ne’er a brother like you?" },
    { r = {"BEATRICE"}, t = "Your father got excellent husbands, if a maid could come by them." },
    { r = {"DON PEDRO"}, t = "Will you have me, lady?" },
    { r = {"BEATRICE"}, t = "No, my lord, unless I might have another for working days: your Grace is too costly to wear every day." },
    { r = {"BEATRICE"}, t = "But, I beseech your Grace, pardon me; I was born to speak all mirth and no matter." },
    { r = {"DON PEDRO"}, t = "Your silence most offends me, and to be merry best becomes you; for out of question, you were born in a merry hour." },
    { r = {"BEATRICE"}, t = "No, sure, my lord, my mother cried; but then there was a star danced, and under that was I born." },
    { r = {"BEATRICE"}, t = "Cousins, God give you joy!" },
    { r = {"LEONATO"}, t = "Niece, will you look to those things I told you of?" },
    { r = {"BEATRICE"}, t = "I cry you mercy, uncle. By your Grace’s pardon." },
    { d = "Exit" },
    { r = {"DON PEDRO"}, t = "By my troth, a pleasant spirited lady." },
    { r = {"LEONATO"}, t = "There’s little of the melancholy element in her, my lord: she is never sad but when she sleeps; and not ever sad then, for I have heard my daughter say, she hath often dreamed of unhappiness and waked herself with laughing." },
    { r = {"DON PEDRO"}, t = "She cannot endure to hear tell of a husband." },
    { r = {"LEONATO"}, t = "O! by no means: she mocks all her wooers out of suit." },
    { r = {"DON PEDRO"}, t = "She were an excellent wife for Benedick." },
    { r = {"LEONATO"}, t = "O Lord! my lord, if they were but a week married, they would talk themselves mad." },
    { r = {"DON PEDRO"}, t = "Count Claudio, when mean you to go to church?" },
    { r = {"CLAUDIO"}, t = "Tomorrow, my lord. Time goes on crutches till love have all his rites." },
    { r = {"LEONATO"}, t = "Not till Monday, my dear son, which is hence a just seven-night; and a time too brief too, to have all things answer my mind." },
    { r = {"DON PEDRO"}, t = "Come, you shake the head at so long a breathing; but, I warrant thee, Claudio, the time shall not go dully by us." },
    { r = {"DON PEDRO"}, t = "I will in the interim undertake one of Hercules’ labours, which is, to bring Signior" },
    { r = {"DON PEDRO"}, t = "Benedick and the Lady Beatrice into a mountain of affection the one with the other." },
    { r = {"DON PEDRO"}, t = "I would fain have it a match; and I doubt not but to fashion it, if you three will but minister such assistance as I shall give you direction." },
    { r = {"LEONATO"}, t = "My lord, I am for you, though it cost me ten nights’ watchings." },
    { r = {"CLAUDIO"}, t = "And I, my lord." },
    { r = {"DON PEDRO"}, t = "And you too, gentle Hero?" },
    { r = {"HERO"}, t = "I will do any modest office, my lord, to help my cousin to a good husband." },
    { r = {"DON PEDRO"}, t = "And Benedick is not the unhopefullest husband that I know." },
    { r = {"DON PEDRO"}, t = "Thus far can I praise him; he is of a noble strain, of approved valour, and confirmed honesty." },
    { r = {"DON PEDRO"}, t = "I will teach you how to humour your cousin, that she shall fall in love with Benedick; and I, with your two helps, will so practise on Benedick that, in despite of his quick wit and his queasy stomach, he shall fall in love with Beatrice." },
    { r = {"DON PEDRO"}, t = "If we can do this, Cupid is no longer an archer: his glory shall be ours, for we are the only love-gods." },
    { r = {"DON PEDRO"}, t = "Go in with me, and I will tell you my drift." },
    { d = "Exeunt" },
    { d = "Act 2, Scene 2. Another room in Leonato’s house.", h = true },
    { d = "Enter Don John and Borachio" },
    { r = {"DON JOHN"}, t = "It is so; the Count Claudio shall marry the daughter of Leonato." },
    { r = {"BORACHIO"}, t = "Yea, my lord; but I can cross it." },
    { r = {"DON JOHN"}, t = "Any bar, any cross, any impediment will be medicinable to me: I am sick in displeasure to him, and whatsoever comes athwart his affection ranges evenly with mine." },
    { r = {"DON JOHN"}, t = "How canst thou cross this marriage?" },
    { r = {"BORACHIO"}, t = "Not honestly, my lord; but so covertly that no dishonesty shall appear in me." },
    { r = {"DON JOHN"}, t = "Show me briefly how." },
    { r = {"BORACHIO"}, t = "I think I told your lordship, a year since, how much I am in the favour of Margaret, the waiting gentlewoman to Hero." },
    { r = {"DON JOHN"}, t = "I remember." },
    { r = {"BORACHIO"}, t = "I can, at any unseasonable instant of the night, appoint her to look out at her lady’s chamber window." },
    { r = {"DON JOHN"}, t = "What life is in that, to be the death of this marriage?" },
    { r = {"BORACHIO"}, t = "The poison of that lies in you to temper." },
    { r = {"BORACHIO"}, t = "Go you to the Prince your brother; spare not to tell him, that he hath wronged his honour in marrying the renowned Claudio,—whose estimation do you mightily hold up,—to a contaminated stale, such a one as Hero." },
    { r = {"DON JOHN"}, t = "What proof shall I make of that?" },
    { r = {"BORACHIO"}, t = "Proof enough to misuse the Prince, to vex Claudio, to undo Hero, and kill Leonato." },
    { r = {"BORACHIO"}, t = "Look you for any other issue?" },
    { r = {"DON JOHN"}, t = "Only to despite them, I will endeavour anything." },
    { r = {"BORACHIO"}, t = "Go then; find me a meet hour to draw Don Pedro and the Count" },
    { r = {"BORACHIO"}, t = "Claudio alone: tell them that you know that Hero loves me; intend a kind of zeal both to the Prince and Claudio, as—" },
    { r = {"BORACHIO"}, t = "in love of your brother’s honour, who hath made this match, and his friend’s reputation, who is thus like to be cozened with the semblance of a maid,— that you have discovered thus." },
    { r = {"BORACHIO"}, t = "They will scarcely believe this without trial: offer them instances, which shall bear no less likelihood than to see me at her chamber window, hear me call Margaret Hero, hear Margaret term me Claudio;" },
    { r = {"BORACHIO"}, t = "and bring them to see this the very night before the intended wedding: for in the meantime I will so fashion the matter that Hero shall be absent;" },
    { r = {"BORACHIO"}, t = "and there shall appear such seeming truth of Hero’s disloyalty, that jealousy shall be called assurance, and all the preparation overthrown." },
    { r = {"DON JOHN"}, t = "Grow this to what adverse issue it can, I will put it in practice." },
    { r = {"DON JOHN"}, t = "Be cunning in the working this, and thy fee is a thousand ducats." },
    { r = {"BORACHIO"}, t = "Be you constant in the accusation, and my cunning shall not shame me." },
    { r = {"DON JOHN"}, t = "I will presently go learn their day of marriage." },
    { d = "Exeunt" },
    { d = "Act 2, Scene 3. Leonato’s Garden.", h = true },
    { d = "Enter Benedick" },
    { r = {"BENEDICK"}, t = "Boy!" },
    { d = "Enter a Boy" },
    { r = {"BOY"}, t = "Signior?" },
    { r = {"BENEDICK"}, t = "In my chamber window lies a book; bring it hither to me in the orchard." },
    { r = {"BOY"}, t = "I am here already, sir." },
    { r = {"BENEDICK"}, t = "I know that; but I would have thee hence, and here again." },
    { d = "Exit Boy" },
    { r = {"BENEDICK"}, t = "I do much wonder that one man, seeing how much another man is a fool when he dedicates his behaviours to love, will, after he hath laughed at such shallow follies in others, become the argument of his own scorn by falling in love:" },
    { r = {"BENEDICK"}, t = "and such a man is Claudio." },
    { r = {"BENEDICK"}, t = "I have known, when there was no music with him but the drum and the fife; and now had he rather hear the tabor and the pipe: I have known when he would have walked ten mile afoot to see a good armour;" },
    { r = {"BENEDICK"}, t = "and now will he lie ten nights awake, carving the fashion of a new doublet." },
    { r = {"BENEDICK"}, t = "He was wont to speak plain and to the purpose, like an honest man and a soldier; and now is he turned orthography; his words are a very fantastical banquet, just so many strange dishes." },
    { r = {"BENEDICK"}, t = "May I be so converted, and see with these eyes?" },
    { r = {"BENEDICK"}, t = "I cannot tell; I think not: I will not be sworn but love may transform me to an oyster; but I’ll take my oath on it, till he have made an oyster of me, he shall never make me such a fool." },
    { r = {"BENEDICK"}, t = "One woman is fair, yet I am well; another is wise, yet I am well; another virtuous, yet I am well; but till all graces be in one woman, one woman shall not come in my grace." },
    { r = {"BENEDICK"}, t = "Rich she shall be, that’s certain; wise, or I’ll none; virtuous, or I’ll never cheapen her; fair, or I’ll never look on her; mild, or come not near me; noble, or not I for an angel;" },
    { r = {"BENEDICK"}, t = "of good discourse, an excellent musician, and her hair shall be of what colour it please God." },
    { r = {"BENEDICK"}, t = "Ha! the Prince and Monsieur Love!" },
    { r = {"BENEDICK"}, t = "I will hide me in the arbour." },
    { d = "Withdraws" },
    { d = "Enter Don Pedro, Leonato and Claudio, followed by Balthasar and Musicians" },
    { r = {"DON PEDRO"}, t = "Come, shall we hear this music?" },
    { r = {"CLAUDIO"}, t = "Yea, my good lord. How still the evening is," },
    { r = {"CLAUDIO"}, t = "As hush’d on purpose to grace harmony!" },
    { r = {"DON PEDRO"}, t = "See you where Benedick hath hid himself?" },
    { r = {"CLAUDIO"}, t = "O! very well, my lord: the music ended," },
    { r = {"CLAUDIO"}, t = "We’ll fit the kid-fox with a penny-worth." },
    { r = {"DON PEDRO"}, t = "Come, Balthasar, we’ll hear that song again." },
    { r = {"BALTHASAR"}, t = "O! good my lord, tax not so bad a voice" },
    { r = {"BALTHASAR"}, t = "To slander music any more than once." },
    { r = {"DON PEDRO"}, t = "It is the witness still of excellency," },
    { r = {"DON PEDRO"}, t = "To put a strange face on his own perfection." },
    { r = {"DON PEDRO"}, t = "I pray thee, sing, and let me woo no more." },
    { r = {"BALTHASAR"}, t = "Because you talk of wooing, I will sing;" },
    { r = {"BALTHASAR"}, t = "Since many a wooer doth commence his suit" },
    { r = {"BALTHASAR"}, t = "To her he thinks not worthy; yet he wooes;" },
    { r = {"BALTHASAR"}, t = "Yet will he swear he loves." },
    { r = {"DON PEDRO"}, t = "Nay, pray thee come;" },
    { r = {"DON PEDRO"}, t = "Or if thou wilt hold longer argument," },
    { r = {"DON PEDRO"}, t = "Do it in notes." },
    { r = {"BALTHASAR"}, t = "Note this before my notes;" },
    { r = {"BALTHASAR"}, t = "There’s not a note of mine that’s worth the noting." },
    { r = {"DON PEDRO"}, t = "Why these are very crotchets that he speaks;" },
    { r = {"DON PEDRO"}, t = "Notes, notes, forsooth, and nothing!" },
    { d = "Music" },
    { r = {"BENEDICK"}, t = "Now, divine air! now is his soul ravished!" },
    { r = {"BENEDICK"}, t = "Is it not strange that sheep’s guts should hale souls out of men’s bodies?" },
    { r = {"BENEDICK"}, t = "Well, a horn for my money, when all’s done." },
    { r = {"BALTHASAR"}, t = "Sigh no more, ladies, sigh no more,", d = "sings" },
    { r = {"BALTHASAR"}, t = "Men were deceivers ever;" },
    { r = {"BALTHASAR"}, t = "One foot in sea, and one on shore," },
    { r = {"BALTHASAR"}, t = "To one thing constant never." },
    { r = {"BALTHASAR"}, t = "Then sigh not so, but let them go," },
    { r = {"BALTHASAR"}, t = "And be you blithe and bonny," },
    { r = {"BALTHASAR"}, t = "Converting all your sounds of woe" },
    { r = {"BALTHASAR"}, t = "Into Hey nonny, nonny." },
    { r = {"BALTHASAR"}, t = "Sing no more ditties, sing no mo", d = "sings" },
    { r = {"BALTHASAR"}, t = "Of dumps so dull and heavy;" },
    { r = {"BALTHASAR"}, t = "The fraud of men was ever so," },
    { r = {"BALTHASAR"}, t = "Since summer first was leavy." },
    { r = {"BALTHASAR"}, t = "Then sigh not so, but let them go," },
    { r = {"BALTHASAR"}, t = "And be you blithe and bonny," },
    { r = {"BALTHASAR"}, t = "Converting all your sounds of woe" },
    { r = {"BALTHASAR"}, t = "Into Hey nonny, nonny." },
    { r = {"DON PEDRO"}, t = "By my troth, a good song." },
    { r = {"BALTHASAR"}, t = "And an ill singer, my lord." },
    { r = {"DON PEDRO"}, t = "Ha, no, no, faith; thou singest well enough for a shift." },
    { r = {"BENEDICK"}, t = "And he had been a dog that should have howled thus, they would have hanged him; and I pray God his bad voice bode no mischief.", d = "Aside" },
    { r = {"BENEDICK"}, t = "I had as lief have heard the night-raven, come what plague could have come after it." },
    { r = {"DON PEDRO"}, t = "Yea, marry; dost thou hear, Balthasar?" },
    { r = {"DON PEDRO"}, t = "I pray thee, get us some excellent music, for tomorrow night we would have it at the Lady Hero’s chamber window." },
    { r = {"BALTHASAR"}, t = "The best I can, my lord." },
    { r = {"DON PEDRO"}, t = "Do so: farewell." },
    { d = "Exeunt Balthasar and Musicians" },
    { r = {"DON PEDRO"}, t = "Come hither, Leonato: what was it you told me of today, that your niece Beatrice was in love with Signior Benedick?" },
    { r = {"CLAUDIO"}, t = "O! ay:" },
    { r = {"CLAUDIO"}, t = "Stalk on, stalk on; the fowl sits.", d = "Aside to Don Pedro" },
    { r = {"CLAUDIO"}, t = "I did never think that lady would have loved any man." },
    { r = {"LEONATO"}, t = "No, nor I neither; but most wonderful that she should so dote on Signior Benedick, whom she hath in all outward behaviours seemed ever to abhor." },
    { r = {"BENEDICK"}, t = "Is’t possible? Sits the wind in that corner?", d = "Aside" },
    { r = {"LEONATO"}, t = "By my troth, my lord, I cannot tell what to think of it but that she loves him with an enraged affection: it is past the infinite of thought." },
    { r = {"DON PEDRO"}, t = "Maybe she doth but counterfeit." },
    { r = {"CLAUDIO"}, t = "Faith, like enough." },
    { r = {"LEONATO"}, t = "O God! counterfeit!" },
    { r = {"LEONATO"}, t = "There was never counterfeit of passion came so near the life of passion as she discovers it." },
    { r = {"DON PEDRO"}, t = "Why, what effects of passion shows she?" },
    { r = {"CLAUDIO"}, t = "Bait the hook well: this fish will bite.", d = "Aside" },
    { r = {"LEONATO"}, t = "What effects, my lord? She will sit you;" },
    { r = {"LEONATO"}, t = "You heard my daughter tell you how.", d = "To Claudio" },
    { r = {"CLAUDIO"}, t = "She did, indeed." },
    { r = {"DON PEDRO"}, t = "How, how, I pray you?" },
    { r = {"DON PEDRO"}, t = "You amaze me: I would have thought her spirit had been invincible against all assaults of affection." },
    { r = {"LEONATO"}, t = "I would have sworn it had, my lord; especially against Benedick." },
    { r = {"BENEDICK"}, t = "I should think this a gull, but that the white-bearded fellow speaks it: knavery cannot, sure, hide itself in such reverence.", d = "Aside" },
    { r = {"CLAUDIO"}, t = "He hath ta’en the infection: hold it up.", d = "Aside" },
    { r = {"DON PEDRO"}, t = "Hath she made her affection known to Benedick?" },
    { r = {"LEONATO"}, t = "No; and swears she never will: that’s her torment." },
    { r = {"CLAUDIO"}, t = "’Tis true, indeed; so your daughter says: ‘Shall I,’ says she, ‘that have so oft encountered him with scorn, write to him that I love him?’" },
    { r = {"LEONATO"}, t = "This says she now when she is beginning to write to him; for she’ll be up twenty times a night, and there will she sit in her smock till she have writ a sheet of paper: my daughter tells us all." },
    { r = {"CLAUDIO"}, t = "Now you talk of a sheet of paper, I remember a pretty jest your daughter told us of." },
    { r = {"LEONATO"}, t = "O! when she had writ it, and was reading it over, she found" },
    { r = {"LEONATO"}, t = "Benedick and Beatrice between the sheet?" },
    { r = {"CLAUDIO"}, t = "That." },
    { r = {"LEONATO"}, t = "O! she tore the letter into a thousand halfpence; railed at herself, that she should be so immodest to write to one that she knew would flout her: ‘I measure him,’ says she, ‘by my own spirit; for I should flout him, if he writ to me;" },
    { r = {"LEONATO"}, t = "yea, though I love him, I should.’" },
    { r = {"CLAUDIO"}, t = "Then down upon her knees she falls, weeps, sobs, beats her heart, tears her hair, prays, curses; ‘O sweet Benedick!" },
    { r = {"CLAUDIO"}, t = "God give me patience!’" },
    { r = {"LEONATO"}, t = "She doth indeed; my daughter says so; and the ecstasy hath so much overborne her, that my daughter is sometimes afeard she will do a desperate outrage to herself." },
    { r = {"LEONATO"}, t = "It is very true." },
    { r = {"DON PEDRO"}, t = "It were good that Benedick knew of it by some other, if she will not discover it." },
    { r = {"CLAUDIO"}, t = "To what end? he would make but a sport of it and torment the poor lady worse." },
    { r = {"DON PEDRO"}, t = "And he should, it were an alms to hang him." },
    { r = {"DON PEDRO"}, t = "She’s an excellent sweet lady, and, out of all suspicion, she is virtuous." },
    { r = {"CLAUDIO"}, t = "And she is exceeding wise." },
    { r = {"DON PEDRO"}, t = "In everything but in loving Benedick." },
    { r = {"LEONATO"}, t = "O! my lord, wisdom and blood combating in so tender a body, we have ten proofs to one that blood hath the victory." },
    { r = {"LEONATO"}, t = "I am sorry for her, as I have just cause, being her uncle and her guardian." },
    { r = {"DON PEDRO"}, t = "I would she had bestowed this dotage on me; I would have daffed all other respects and made her half myself." },
    { r = {"DON PEDRO"}, t = "I pray you, tell Benedick of it, and hear what he will say." },
    { r = {"LEONATO"}, t = "Were it good, think you?" },
    { r = {"CLAUDIO"}, t = "Hero thinks surely she will die; for she says she will die if he love her not, and she will die ere she make her love known, and she will die if he woo her, rather than she will bate one breath of her accustomed crossness." },
    { r = {"DON PEDRO"}, t = "She doth well: if she should make tender of her love, ’tis very possible he’ll scorn it; for the man,—as you know all,—hath a contemptible spirit." },
    { r = {"CLAUDIO"}, t = "He is a very proper man." },
    { r = {"DON PEDRO"}, t = "He hath indeed a good outward happiness." },
    { r = {"CLAUDIO"}, t = "’Fore God, and in my mind, very wise." },
    { r = {"DON PEDRO"}, t = "He doth indeed show some sparks that are like wit." },
    { r = {"CLAUDIO"}, t = "And I take him to be valiant." },
    { r = {"DON PEDRO"}, t = "As Hector, I assure you: and in the managing of quarrels you may say he is wise; for either he avoids them with great discretion, or undertakes them with a most Christian-like fear." },
    { r = {"LEONATO"}, t = "If he do fear God, a’ must necessarily keep peace: if he break the peace, he ought to enter into a quarrel with fear and trembling." },
    { r = {"DON PEDRO"}, t = "And so will he do; for the man doth fear God, howsoever it seems not in him by some large jests he will make." },
    { r = {"DON PEDRO"}, t = "Well, I am sorry for your niece." },
    { r = {"DON PEDRO"}, t = "Shall we go seek Benedick and tell him of her love?" },
    { r = {"CLAUDIO"}, t = "Never tell him, my lord: let her wear it out with good counsel." },
    { r = {"LEONATO"}, t = "Nay, that’s impossible: she may wear her heart out first." },
    { r = {"DON PEDRO"}, t = "Well, we will hear further of it by your daughter: let it cool the while." },
    { r = {"DON PEDRO"}, t = "I love Benedick well, and I could wish he would modestly examine himself, to see how much he is unworthy so good a lady." },
    { r = {"LEONATO"}, t = "My lord, will you walk? dinner is ready." },
    { r = {"CLAUDIO"}, t = "If he do not dote on her upon this, I will never trust my expectation.", d = "Aside" },
    { r = {"DON PEDRO"}, t = "Let there be the same net spread for her; and that must your daughter and her gentlewoman carry.", d = "Aside" },
    { r = {"DON PEDRO"}, t = "The sport will be, when they hold one an opinion of another’s dotage, and no such matter: that’s the scene that I would see, which will be merely a dumb show." },
    { r = {"DON PEDRO"}, t = "Let us send her to call him in to dinner." },
    { d = "Exeunt Don Pedro, Claudio and Leonato" },
    { r = {"BENEDICK"}, t = "This can be no trick: the conference was sadly borne.", d = "Advancing from the arbour" },
    { r = {"BENEDICK"}, t = "They have the truth of this from Hero." },
    { r = {"BENEDICK"}, t = "They seem to pity the lady: it seems her affections have their full bent." },
    { r = {"BENEDICK"}, t = "Love me? why, it must be requited." },
    { r = {"BENEDICK"}, t = "I hear how I am censured: they say I will bear myself proudly, if I perceive the love come from her; they say too that she will rather die than give any sign of affection." },
    { r = {"BENEDICK"}, t = "I did never think to marry: I must not seem proud: happy are they that hear their detractions, and can put them to mending." },
    { r = {"BENEDICK"}, t = "They say the lady is fair: ’tis a truth, I can bear them witness; and virtuous: ’tis so," },
    { r = {"BENEDICK"}, t = "I cannot reprove it; and wise, but for loving me: by my troth, it is no addition to her wit, nor no great argument of her folly, for I will be horribly in love with her." },
    { r = {"BENEDICK"}, t = "I may chance have some odd quirks and remnants of wit broken on me, because I have railed so long against marriage; but doth not the appetite alter?" },
    { r = {"BENEDICK"}, t = "A man loves the meat in his youth that he cannot endure in his age." },
    { r = {"BENEDICK"}, t = "Shall quips and sentences and these paper bullets of the brain awe a man from the career of his humour?" },
    { r = {"BENEDICK"}, t = "No; the world must be peopled." },
    { r = {"BENEDICK"}, t = "When I said I would die a bachelor, I did not think I should live till I were married." },
    { r = {"BENEDICK"}, t = "Here comes Beatrice." },
    { r = {"BENEDICK"}, t = "By this day! she’s a fair lady: I do spy some marks of love in her." },
    { d = "Enter Beatrice" },
    { r = {"BEATRICE"}, t = "Against my will I am sent to bid you come in to dinner." },
    { r = {"BENEDICK"}, t = "Fair Beatrice, I thank you for your pains." },
    { r = {"BEATRICE"}, t = "I took no more pains for those thanks than you take pains to thank me: if it had been painful, I would not have come." },
    { r = {"BENEDICK"}, t = "You take pleasure then in the message?" },
    { r = {"BEATRICE"}, t = "Yea, just so much as you may take upon a knife’s point, and choke a daw withal." },
    { r = {"BEATRICE"}, t = "You have no stomach, signior: fare you well." },
    { d = "Exit" },
    { r = {"BENEDICK"}, t = "Ha!" },
    { r = {"BENEDICK"}, t = "‘Against my will I am sent to bid you come in to dinner,’ there’s a double meaning in that." },
    { r = {"BENEDICK"}, t = "‘I took no more pains for those thanks than you took pains to thank me,’ that’s as much as to say, Any pains that I take for you is as easy as thanks." },
    { r = {"BENEDICK"}, t = "If I do not take pity of her, I am a villain; if I do not love her, I am a Jew." },
    { r = {"BENEDICK"}, t = "I will go get her picture." },
    { d = "Exit" },
    { d = "Act 3, Scene 1. Leonato’s Garden.", h = true },
    { d = "Enter Hero, Margaret and Ursula" },
    { r = {"HERO"}, t = "Good Margaret, run thee to the parlour;" },
    { r = {"HERO"}, t = "There shalt thou find my cousin Beatrice" },
    { r = {"HERO"}, t = "Proposing with the Prince and Claudio:" },
    { r = {"HERO"}, t = "Whisper her ear, and tell her, I and Ursala" },
    { r = {"HERO"}, t = "Walk in the orchard, and our whole discourse" },
    { r = {"HERO"}, t = "Is all of her; say that thou overheard’st us," },
    { r = {"HERO"}, t = "And bid her steal into the pleached bower," },
    { r = {"HERO"}, t = "Where honey-suckles, ripen’d by the sun," },
    { r = {"HERO"}, t = "Forbid the sun to enter; like favourites," },
    { r = {"HERO"}, t = "Made proud by princes, that advance their pride" },
    { r = {"HERO"}, t = "Against that power that bred it. There will she hide her," },
    { r = {"HERO"}, t = "To listen our propose. This is thy office;" },
    { r = {"HERO"}, t = "Bear thee well in it and leave us alone." },
    { r = {"MARGARET"}, t = "I’ll make her come, I warrant you, presently." },
    { d = "Exit" },
    { r = {"HERO"}, t = "Now, Ursula, when Beatrice doth come," },
    { r = {"HERO"}, t = "As we do trace this alley up and down," },
    { r = {"HERO"}, t = "Our talk must only be of Benedick:" },
    { r = {"HERO"}, t = "When I do name him, let it be thy part" },
    { r = {"HERO"}, t = "To praise him more than ever man did merit." },
    { r = {"HERO"}, t = "My talk to thee must be how Benedick" },
    { r = {"HERO"}, t = "Is sick in love with Beatrice: of this matter" },
    { r = {"HERO"}, t = "Is little Cupid’s crafty arrow made," },
    { r = {"HERO"}, t = "That only wounds by hearsay." },
    { d = "Enter Beatrice behind" },
    { r = {"HERO"}, t = "Now begin;" },
    { r = {"HERO"}, t = "For look where Beatrice, like a lapwing, runs" },
    { r = {"HERO"}, t = "Close by the ground, to hear our conference." },
    { r = {"URSULA"}, t = "The pleasant’st angling is to see the fish" },
    { r = {"URSULA"}, t = "Cut with her golden oars the silver stream," },
    { r = {"URSULA"}, t = "And greedily devour the treacherous bait:" },
    { r = {"URSULA"}, t = "So angle we for Beatrice; who even now" },
    { r = {"URSULA"}, t = "Is couched in the woodbine coverture." },
    { r = {"URSULA"}, t = "Fear you not my part of the dialogue." },
    { r = {"HERO"}, t = "Then go we near her, that her ear lose nothing" },
    { r = {"HERO"}, t = "Of the false sweet bait that we lay for it." },
    { d = "They advance to the bower" },
    { r = {"HERO"}, t = "No, truly, Ursula, she is too disdainful;" },
    { r = {"HERO"}, t = "I know her spirits are as coy and wild" },
    { r = {"HERO"}, t = "As haggards of the rock." },
    { r = {"URSULA"}, t = "But are you sure" },
    { r = {"URSULA"}, t = "That Benedick loves Beatrice so entirely?" },
    { r = {"HERO"}, t = "So says the Prince, and my new-trothed lord." },
    { r = {"URSULA"}, t = "And did they bid you tell her of it, madam?" },
    { r = {"HERO"}, t = "They did entreat me to acquaint her of it;" },
    { r = {"HERO"}, t = "But I persuaded them, if they lov’d Benedick," },
    { r = {"HERO"}, t = "To wish him wrestle with affection," },
    { r = {"HERO"}, t = "And never to let Beatrice know of it." },
    { r = {"URSULA"}, t = "Why did you so? Doth not the gentleman" },
    { r = {"URSULA"}, t = "Deserve as full as fortunate a bed" },
    { r = {"URSULA"}, t = "As ever Beatrice shall couch upon?" },
    { r = {"HERO"}, t = "O god of love! I know he doth deserve" },
    { r = {"HERO"}, t = "As much as may be yielded to a man;" },
    { r = {"HERO"}, t = "But Nature never fram’d a woman’s heart" },
    { r = {"HERO"}, t = "Of prouder stuff than that of Beatrice;" },
    { r = {"HERO"}, t = "Disdain and scorn ride sparkling in her eyes," },
    { r = {"HERO"}, t = "Misprising what they look on, and her wit" },
    { r = {"HERO"}, t = "Values itself so highly, that to her" },
    { r = {"HERO"}, t = "All matter else seems weak. She cannot love," },
    { r = {"HERO"}, t = "Nor take no shape nor project of affection," },
    { r = {"HERO"}, t = "She is so self-endear’d." },
    { r = {"URSULA"}, t = "Sure I think so;" },
    { r = {"URSULA"}, t = "And therefore certainly it were not good" },
    { r = {"URSULA"}, t = "She knew his love, lest she make sport at it." },
    { r = {"HERO"}, t = "Why, you speak truth. I never yet saw man," },
    { r = {"HERO"}, t = "How wise, how noble, young, how rarely featur’d," },
    { r = {"HERO"}, t = "But she would spell him backward: if fair-fac’d," },
    { r = {"HERO"}, t = "She would swear the gentleman should be her sister;" },
    { r = {"HERO"}, t = "If black, why, Nature, drawing of an antick," },
    { r = {"HERO"}, t = "Made a foul blot; if tall, a lance ill-headed;" },
    { r = {"HERO"}, t = "If low, an agate very vilely cut;" },
    { r = {"HERO"}, t = "If speaking, why, a vane blown with all winds;" },
    { r = {"HERO"}, t = "If silent, why, a block moved with none." },
    { r = {"HERO"}, t = "So turns she every man the wrong side out," },
    { r = {"HERO"}, t = "And never gives to truth and virtue that" },
    { r = {"HERO"}, t = "Which simpleness and merit purchaseth." },
    { r = {"URSULA"}, t = "Sure, sure, such carping is not commendable." },
    { r = {"HERO"}, t = "No; not to be so odd, and from all fashions," },
    { r = {"HERO"}, t = "As Beatrice is, cannot be commendable." },
    { r = {"HERO"}, t = "But who dare tell her so? If I should speak," },
    { r = {"HERO"}, t = "She would mock me into air: O! she would laugh me" },
    { r = {"HERO"}, t = "Out of myself, press me to death with wit." },
    { r = {"HERO"}, t = "Therefore let Benedick, like cover’d fire," },
    { r = {"HERO"}, t = "Consume away in sighs, waste inwardly:" },
    { r = {"HERO"}, t = "It were a better death than die with mocks," },
    { r = {"HERO"}, t = "Which is as bad as die with tickling." },
    { r = {"URSULA"}, t = "Yet tell her of it: hear what she will say." },
    { r = {"HERO"}, t = "No; rather I will go to Benedick," },
    { r = {"HERO"}, t = "And counsel him to fight against his passion." },
    { r = {"HERO"}, t = "And, truly, I’ll devise some honest slanders" },
    { r = {"HERO"}, t = "To stain my cousin with. One doth not know" },
    { r = {"HERO"}, t = "How much an ill word may empoison liking." },
    { r = {"URSULA"}, t = "O! do not do your cousin such a wrong." },
    { r = {"URSULA"}, t = "She cannot be so much without true judgment,—" },
    { r = {"URSULA"}, t = "Having so swift and excellent a wit" },
    { r = {"URSULA"}, t = "As she is priz’d to have,—as to refuse" },
    { r = {"URSULA"}, t = "So rare a gentleman as Signior Benedick." },
    { r = {"HERO"}, t = "He is the only man of Italy," },
    { r = {"HERO"}, t = "Always excepted my dear Claudio." },
    { r = {"URSULA"}, t = "I pray you, be not angry with me, madam," },
    { r = {"URSULA"}, t = "Speaking my fancy: Signior Benedick," },
    { r = {"URSULA"}, t = "For shape, for bearing, argument and valour," },
    { r = {"URSULA"}, t = "Goes foremost in report through Italy." },
    { r = {"HERO"}, t = "Indeed, he hath an excellent good name." },
    { r = {"URSULA"}, t = "His excellence did earn it, ere he had it." },
    { r = {"URSULA"}, t = "When are you married, madam?" },
    { r = {"HERO"}, t = "Why, every day, tomorrow. Come, go in:" },
    { r = {"HERO"}, t = "I’ll show thee some attires, and have thy counsel" },
    { r = {"HERO"}, t = "Which is the best to furnish me tomorrow." },
    { r = {"URSULA"}, t = "She’s lim’d, I warrant you," },
    { r = {"URSULA"}, t = "We have caught her, madam." },
    { r = {"HERO"}, t = "If it prove so, then loving goes by haps:" },
    { r = {"HERO"}, t = "Some Cupid kills with arrows, some with traps." },
    { d = "Exeunt Hero and Ursula" },
    { r = {"BEATRICE"}, t = "What fire is in mine ears? Can this be true?", d = "Advancing" },
    { r = {"BEATRICE"}, t = "Stand I condemn’d for pride and scorn so much?" },
    { r = {"BEATRICE"}, t = "Contempt, farewell! and maiden pride, adieu!" },
    { r = {"BEATRICE"}, t = "No glory lives behind the back of such." },
    { r = {"BEATRICE"}, t = "And, Benedick, love on; I will requite thee," },
    { r = {"BEATRICE"}, t = "Taming my wild heart to thy loving hand:" },
    { r = {"BEATRICE"}, t = "If thou dost love, my kindness shall incite thee" },
    { r = {"BEATRICE"}, t = "To bind our loves up in a holy band;" },
    { r = {"BEATRICE"}, t = "For others say thou dost deserve, and I" },
    { r = {"BEATRICE"}, t = "Believe it better than reportingly." },
    { d = "Exit" },
    { d = "Act 3, Scene 2. A Room in Leonato’s House.", h = true },
    { d = "Enter Don Pedro, Claudio, Benedick and Leonato" },
    { r = {"DON PEDRO"}, t = "I do but stay till your marriage be consummate, and then go I toward Arragon." },
    { r = {"CLAUDIO"}, t = "I’ll bring you thither, my lord, if you’ll vouchsafe me." },
    { r = {"DON PEDRO"}, t = "Nay, that would be as great a soil in the new gloss of your marriage, as to show a child his new coat and forbid him to wear it." },
    { r = {"DON PEDRO"}, t = "I will only be bold with Benedick for his company; for, from the crown of his head to the sole of his foot, he is all mirth; he hath twice or thrice cut Cupid’s bowstring, and the little hangman dare not shoot at him." },
    { r = {"DON PEDRO"}, t = "He hath a heart as sound as a bell, and his tongue is the clapper; for what his heart thinks, his tongue speaks." },
    { r = {"BENEDICK"}, t = "Gallants, I am not as I have been." },
    { r = {"LEONATO"}, t = "So say I: methinks you are sadder." },
    { r = {"CLAUDIO"}, t = "I hope he be in love." },
    { r = {"DON PEDRO"}, t = "Hang him, truant! there’s no true drop of blood in him to be truly touched with love." },
    { r = {"DON PEDRO"}, t = "If he be sad, he wants money." },
    { r = {"BENEDICK"}, t = "I have the tooth-ache." },
    { r = {"DON PEDRO"}, t = "Draw it." },
    { r = {"BENEDICK"}, t = "Hang it." },
    { r = {"CLAUDIO"}, t = "You must hang it first, and draw it afterwards." },
    { r = {"DON PEDRO"}, t = "What! sigh for the tooth-ache?" },
    { r = {"LEONATO"}, t = "Where is but a humour or a worm?" },
    { r = {"BENEDICK"}, t = "Well, everyone can master a grief but he that has it." },
    { r = {"CLAUDIO"}, t = "Yet say I, he is in love." },
    { r = {"DON PEDRO"}, t = "There is no appearance of fancy in him, unless it be a fancy that he hath to strange disguises; as to be a Dutchman today, a Frenchman tomorrow;" },
    { r = {"DON PEDRO"}, t = "or in the shape of two countries at once, as a German from the waist downward, all slops, and a Spaniard from the hip upward, no doublet." },
    { r = {"DON PEDRO"}, t = "Unless he have a fancy to this foolery, as it appears he hath, he is no fool for fancy, as you would have it appear he is." },
    { r = {"CLAUDIO"}, t = "If he be not in love with some woman, there is no believing old signs: a’ brushes his hat a mornings; what should that bode?" },
    { r = {"DON PEDRO"}, t = "Hath any man seen him at the barber’s?" },
    { r = {"CLAUDIO"}, t = "No, but the barber’s man hath been seen with him; and the old ornament of his cheek hath already stuffed tennis balls." },
    { r = {"LEONATO"}, t = "Indeed he looks younger than he did, by the loss of a beard." },
    { r = {"DON PEDRO"}, t = "Nay, a’ rubs himself with civet: can you smell him out by that?" },
    { r = {"CLAUDIO"}, t = "That’s as much as to say the sweet youth’s in love." },
    { r = {"DON PEDRO"}, t = "The greatest note of it is his melancholy." },
    { r = {"CLAUDIO"}, t = "And when was he wont to wash his face?" },
    { r = {"DON PEDRO"}, t = "Yea, or to paint himself? for the which, I hear what they say of him." },
    { r = {"CLAUDIO"}, t = "Nay, but his jesting spirit; which is now crept into a lute-string, and now governed by stops." },
    { r = {"DON PEDRO"}, t = "Indeed, that tells a heavy tale for him. Conclude, conclude he is in love." },
    { r = {"CLAUDIO"}, t = "Nay, but I know who loves him." },
    { r = {"DON PEDRO"}, t = "That would I know too: I warrant, one that knows him not." },
    { r = {"CLAUDIO"}, t = "Yes, and his ill conditions; and in despite of all, dies for him." },
    { r = {"DON PEDRO"}, t = "She shall be buried with her face upwards." },
    { r = {"BENEDICK"}, t = "Yet is this no charm for the tooth-ache." },
    { r = {"BENEDICK"}, t = "Old signior, walk aside with me: I have studied eight or nine wise words to speak to you, which these hobby-horses must not hear." },
    { d = "Exeunt Benedick and Leonato" },
    { r = {"DON PEDRO"}, t = "For my life, to break with him about Beatrice." },
    { r = {"CLAUDIO"}, t = "’Tis even so." },
    { r = {"CLAUDIO"}, t = "Hero and Margaret have by this played their parts with Beatrice, and then the two bears will not bite one another when they meet." },
    { d = "Enter Don John" },
    { r = {"DON JOHN"}, t = "My lord and brother, God save you!" },
    { r = {"DON PEDRO"}, t = "Good den, brother." },
    { r = {"DON JOHN"}, t = "If your leisure served, I would speak with you." },
    { r = {"DON PEDRO"}, t = "In private?" },
    { r = {"DON JOHN"}, t = "If it please you; yet Count Claudio may hear, for what I would speak of concerns him." },
    { r = {"DON PEDRO"}, t = "What’s the matter?" },
    { r = {"DON JOHN"}, t = "Means your lordship to be married tomorrow?", d = "To Claudio" },
    { r = {"DON PEDRO"}, t = "You know he does." },
    { r = {"DON JOHN"}, t = "I know not that, when he knows what I know." },
    { r = {"CLAUDIO"}, t = "If there be any impediment, I pray you discover it." },
    { r = {"DON JOHN"}, t = "You may think I love you not: let that appear hereafter, and aim better at me by that I now will manifest." },
    { r = {"DON JOHN"}, t = "For my brother, I think he holds you well, and in dearness of heart hath holp to effect your ensuing marriage; surely suit ill-spent and labour ill bestowed!" },
    { r = {"DON PEDRO"}, t = "Why, what’s the matter?" },
    { r = {"DON JOHN"}, t = "I came hither to tell you; and circumstances shortened,—for she has been too long a talking of,—the lady is disloyal." },
    { r = {"CLAUDIO"}, t = "Who, Hero?" },
    { r = {"DON JOHN"}, t = "Even she: Leonato’s Hero, your Hero, every man’s Hero." },
    { r = {"CLAUDIO"}, t = "Disloyal?" },
    { r = {"DON JOHN"}, t = "The word’s too good to paint out her wickedness; I could say, she were worse: think you of a worse title, and I will fit her to it." },
    { r = {"DON JOHN"}, t = "Wonder not till further warrant: go but with me tonight, you shall see her chamber window entered, even the night before her wedding-day: if you love her then, tomorrow wed her; but it would better fit your honour to change your mind." },
    { r = {"CLAUDIO"}, t = "May this be so?" },
    { r = {"DON PEDRO"}, t = "I will not think it." },
    { r = {"DON JOHN"}, t = "If you dare not trust that you see, confess not that you know." },
    { r = {"DON JOHN"}, t = "If you will follow me, I will show you enough; and when you have seen more and heard more, proceed accordingly." },
    { r = {"CLAUDIO"}, t = "If I see anything tonight why I should not marry her tomorrow, in the congregation, where I should wed, there will I shame her." },
    { r = {"DON PEDRO"}, t = "And, as I wooed for thee to obtain her, I will join with thee to disgrace her." },
    { r = {"DON JOHN"}, t = "I will disparage her no farther till you are my witnesses: bear it coldly but till midnight, and let the issue show itself." },
    { r = {"DON PEDRO"}, t = "O day untowardly turned!" },
    { r = {"CLAUDIO"}, t = "O mischief strangely thwarting!" },
    { r = {"DON JOHN"}, t = "O plague right well prevented!" },
    { r = {"DON JOHN"}, t = "So will you say when you have seen the sequel." },
    { d = "Exeunt" },
    { d = "Act 3, Scene 3. A Street.", h = true },
    { d = "Enter Dogberry and Verges, with the Watch" },
    { r = {"DOGBERRY"}, t = "Are you good men and true?" },
    { r = {"VERGES"}, t = "Yea, or else it were pity but they should suffer salvation, body and soul." },
    { r = {"DOGBERRY"}, t = "Nay, that were a punishment too good for them, if they should have any allegiance in them, being chosen for the Prince’s watch." },
    { r = {"VERGES"}, t = "Well, give them their charge, neighbour Dogberry." },
    { r = {"DOGBERRY"}, t = "First, who think you the most desartless man to be constable?" },
    { r = {"FIRST WATCH"}, t = "Hugh Oatcake, sir, or George Seacoal; for they can write and read." },
    { r = {"DOGBERRY"}, t = "Come hither, neighbour Seacoal." },
    { r = {"DOGBERRY"}, t = "God hath blessed you with a good name: to be a well-favoured man is the gift of Fortune; but to write and read comes by Nature." },
    { r = {"SECOND WATCH"}, t = "Both which, Master Constable," },
    { r = {"DOGBERRY"}, t = "You have: I knew it would be your answer." },
    { r = {"DOGBERRY"}, t = "Well, for your favour, sir, why, give God thanks, and make no boast of it; and for your writing and reading, let that appear when there is no need of such vanity." },
    { r = {"DOGBERRY"}, t = "You are thought here to be the most senseless and fit man for the constable of the watch; therefore bear you the lanthorn." },
    { r = {"DOGBERRY"}, t = "This is your charge: you shall comprehend all vagrom men; you are to bid any man stand, in the Prince’s name." },
    { r = {"SECOND WATCH"}, t = "How, if a’ will not stand?" },
    { r = {"DOGBERRY"}, t = "Why, then, take no note of him, but let him go; and presently call the rest of the watch together, and thank God you are rid of a knave." },
    { r = {"VERGES"}, t = "If he will not stand when he is bidden, he is none of the Prince’s subjects." },
    { r = {"DOGBERRY"}, t = "True, and they are to meddle with none but the Prince’s subjects." },
    { r = {"DOGBERRY"}, t = "You shall also make no noise in the streets: for, for the watch to babble and to talk is most tolerable and not to be endured." },
    { r = {"SECOND WATCH"}, t = "We will rather sleep than talk: we know what belongs to a watch." },
    { r = {"DOGBERRY"}, t = "Why, you speak like an ancient and most quiet watchman, for I cannot see how sleeping should offend; only have a care that your bills be not stolen." },
    { r = {"DOGBERRY"}, t = "Well, you are to call at all the alehouses, and bid those that are drunk get them to bed." },
    { r = {"SECOND WATCH"}, t = "How if they will not?" },
    { r = {"DOGBERRY"}, t = "Why then, let them alone till they are sober: if they make you not then the better answer, you may say they are not the men you took them for." },
    { r = {"SECOND WATCH"}, t = "Well, sir." },
    { r = {"DOGBERRY"}, t = "If you meet a thief, you may suspect him, by virtue of your office, to be no true man; and, for such kind of men, the less you meddle or make with them, why, the more is for your honesty." },
    { r = {"SECOND WATCH"}, t = "If we know him to be a thief, shall we not lay hands on him?" },
    { r = {"DOGBERRY"}, t = "Truly, by your office, you may; but I think they that touch pitch will be defiled." },
    { r = {"DOGBERRY"}, t = "The most peaceable way for you, if you do take a thief, is to let him show himself what he is and steal out of your company." },
    { r = {"VERGES"}, t = "You have been always called a merciful man, partner." },
    { r = {"DOGBERRY"}, t = "Truly, I would not hang a dog by my will, much more a man who hath any honesty in him." },
    { r = {"VERGES"}, t = "If you hear a child cry in the night, you must call to the nurse and bid her still it." },
    { r = {"SECOND WATCH"}, t = "How if the nurse be asleep and will not hear us?" },
    { r = {"DOGBERRY"}, t = "Why then, depart in peace, and let the child wake her with crying; for the ewe that will not hear her lamb when it baes, will never answer a calf when he bleats." },
    { r = {"VERGES"}, t = "’Tis very true." },
    { r = {"DOGBERRY"}, t = "This is the end of the charge." },
    { r = {"DOGBERRY"}, t = "You constable, are to present the Prince’s own person: if you meet the Prince in the night, you may stay him." },
    { r = {"VERGES"}, t = "Nay, by’r lady, that I think, a’ cannot." },
    { r = {"DOGBERRY"}, t = "Five shillings to one on’t, with any man that knows the statutes, he may stay him: marry, not without the Prince be willing; for, indeed, the watch ought to offend no man, and it is an offence to stay a man against his will." },
    { r = {"VERGES"}, t = "By’r lady, I think it be so." },
    { r = {"DOGBERRY"}, t = "Ha, ah, ha!" },
    { r = {"DOGBERRY"}, t = "Well, masters, good night: an there be any matter of weight chances, call up me: keep your fellows’ counsels and your own, and good night." },
    { r = {"DOGBERRY"}, t = "Come, neighbour." },
    { r = {"SECOND WATCH"}, t = "Well, masters, we hear our charge: let us go sit here upon the church bench till two, and then all to bed." },
    { r = {"DOGBERRY"}, t = "One word more, honest neighbours. I pray you, watch about" },
    { r = {"DOGBERRY"}, t = "Signior Leonato’s door; for the wedding being there tomorrow, there is a great coil tonight." },
    { r = {"DOGBERRY"}, t = "Adieu; be vigitant, I beseech you." },
    { d = "Exeunt Dogberry and Verges" },
    { d = "Enter Borachio and Conrade" },
    { r = {"BORACHIO"}, t = "What, Conrade!" },
    { r = {"WATCH"}, t = "Peace! stir not.", d = "Aside" },
    { r = {"BORACHIO"}, t = "Conrade, I say!" },
    { r = {"CONRADE"}, t = "Here, man. I am at thy elbow." },
    { r = {"BORACHIO"}, t = "Mass, and my elbow itched; I thought there would a scab follow." },
    { r = {"CONRADE"}, t = "I will owe thee an answer for that; and now forward with thy tale." },
    { r = {"BORACHIO"}, t = "Stand thee close then under this penthouse, for it drizzles rain, and I will, like a true drunkard, utter all to thee." },
    { r = {"WATCH"}, t = "Some treason, masters; yet stand close.", d = "Aside" },
    { r = {"BORACHIO"}, t = "Therefore know, I have earned of Don John a thousand ducats." },
    { r = {"CONRADE"}, t = "Is it possible that any villainy should be so dear?" },
    { r = {"BORACHIO"}, t = "Thou shouldst rather ask if it were possible any villainy should be so rich; for when rich villains have need of poor ones, poor ones may make what price they will." },
    { r = {"CONRADE"}, t = "I wonder at it." },
    { r = {"BORACHIO"}, t = "That shows thou art unconfirmed." },
    { r = {"BORACHIO"}, t = "Thou knowest that the fashion of a doublet, or a hat, or a cloak, is nothing to a man." },
    { r = {"CONRADE"}, t = "Yes, it is apparel." },
    { r = {"BORACHIO"}, t = "I mean, the fashion." },
    { r = {"CONRADE"}, t = "Yes, the fashion is the fashion." },
    { r = {"BORACHIO"}, t = "Tush!" },
    { r = {"BORACHIO"}, t = "I may as well say the fool’s the fool." },
    { r = {"BORACHIO"}, t = "But seest thou not what a deformed thief this fashion is?" },
    { r = {"WATCH"}, t = "I know that Deformed; a’ has been a vile thief this seven years; a’ goes up and down like a gentleman: I remember his name.", d = "Aside" },
    { r = {"BORACHIO"}, t = "Didst thou not hear somebody?" },
    { r = {"CONRADE"}, t = "No: ’twas the vane on the house." },
    { r = {"BORACHIO"}, t = "Seest thou not, I say, what a deformed thief this fashion is? how giddily he turns about all the hot bloods between fourteen and five-and-thirty?" },
    { r = {"BORACHIO"}, t = "sometime fashioning them like Pharaoh’s soldiers in the reechy painting; sometime like god Bel’s priests in the old church window;" },
    { r = {"BORACHIO"}, t = "sometime like the shaven Hercules in the smirched worm-eaten tapestry, where his codpiece seems as massy as his club?" },
    { r = {"CONRADE"}, t = "All this I see, and I see that the fashion wears out more apparel than the man." },
    { r = {"CONRADE"}, t = "But art not thou thyself giddy with the fashion too, that thou hast shifted out of thy tale into telling me of the fashion?" },
    { r = {"BORACHIO"}, t = "Not so neither; but know, that I have tonight wooed Margaret, the Lady Hero’s gentlewoman, by the name of Hero: she leans me out at her mistress’ chamber window, bids me a thousand times good night,— I tell this tale vilely: —" },
    { r = {"BORACHIO"}, t = "I should first tell thee how the Prince, Claudio, and my master, planted and placed and possessed by my master Don John, saw afar off in the orchard this amiable encounter." },
    { r = {"CONRADE"}, t = "And thought they Margaret was Hero?" },
    { r = {"BORACHIO"}, t = "Two of them did, the Prince and Claudio; but the devil my master, knew she was Margaret;" },
    { r = {"BORACHIO"}, t = "and partly by his oaths, which first possessed them, partly by the dark night, which did deceive them, but chiefly by my villainy, which did confirm any slander that Don John had made, away went Claudio enraged;" },
    { r = {"BORACHIO"}, t = "swore he would meet her, as he was appointed, next morning at the temple, and there, before the whole congregation, shame her with what he saw o’er night, and send her home again without a husband." },
    { r = {"FIRST WATCH"}, t = "We charge you in the Prince’s name, stand!" },
    { r = {"SECOND WATCH"}, t = "Call up the right Master Constable." },
    { r = {"SECOND WATCH"}, t = "We have here recovered the most dangerous piece of lechery that ever was known in the commonwealth." },
    { r = {"FIRST WATCH"}, t = "And one Deformed is one of them: I know him, a’ wears a lock." },
    { r = {"CONRADE"}, t = "Masters, masters!" },
    { r = {"SECOND WATCH"}, t = "You’ll be made bring Deformed forth, I warrant you." },
    { r = {"CONRADE"}, t = "Masters," },
    { r = {"FIRST WATCH"}, t = "Never speak: we charge you let us obey you to go with us." },
    { r = {"BORACHIO"}, t = "We are like to prove a goodly commodity, being taken up of these men’s bills." },
    { r = {"CONRADE"}, t = "A commodity in question, I warrant you. Come, we’ll obey you." },
    { d = "Exeunt" },
    { d = "Act 3, Scene 4. A Room in Leonato’s House.", h = true },
    { d = "Enter Hero, Margaret and Ursula" },
    { r = {"HERO"}, t = "Good Ursula, wake my cousin Beatrice, and desire her to rise." },
    { r = {"URSULA"}, t = "I will, lady." },
    { r = {"HERO"}, t = "And bid her come hither." },
    { r = {"URSULA"}, t = "Well." },
    { d = "Exit" },
    { r = {"MARGARET"}, t = "Troth, I think your other rebato were better." },
    { r = {"HERO"}, t = "No, pray thee, good Meg, I’ll wear this." },
    { r = {"MARGARET"}, t = "By my troth’s not so good; and I warrant your cousin will say so." },
    { r = {"HERO"}, t = "My cousin’s a fool, and thou art another: I’ll wear none but this." },
    { r = {"MARGARET"}, t = "I like the new tire within excellently, if the hair were a thought browner; and your gown’s a most rare fashion, i’ faith." },
    { r = {"MARGARET"}, t = "I saw the Duchess of Milan’s gown that they praise so." },
    { r = {"HERO"}, t = "O! that exceeds, they say." },
    { r = {"MARGARET"}, t = "By my troth ’s but a night-gown in respect of yours: cloth o’ gold, and cuts, and laced with silver, set with pearls, down sleeves, side sleeves, and skirts round, underborne with a bluish tinsel;" },
    { r = {"MARGARET"}, t = "but for a fine, quaint, graceful, and excellent fashion, yours is worth ten on’t." },
    { r = {"HERO"}, t = "God give me joy to wear it! for my heart is exceeding heavy." },
    { r = {"MARGARET"}, t = "’Twill be heavier soon by the weight of a man." },
    { r = {"HERO"}, t = "Fie upon thee! art not ashamed?" },
    { r = {"MARGARET"}, t = "Of what, lady? of speaking honourably?" },
    { r = {"MARGARET"}, t = "Is not marriage honourable in a beggar?" },
    { r = {"MARGARET"}, t = "Is not your lord honourable without marriage?" },
    { r = {"MARGARET"}, t = "I think you would have me say, saving your reverence, ‘a husband:’ an bad thinking do not wrest true speaking, I’ll offend nobody." },
    { r = {"MARGARET"}, t = "Is there any harm in ‘the heavier for a husband’?" },
    { r = {"MARGARET"}, t = "None, I think, and it be the right husband and the right wife; otherwise ’tis light, and not heavy: ask my Lady Beatrice else; here she comes." },
    { d = "Enter Beatrice" },
    { r = {"HERO"}, t = "Good morrow, coz." },
    { r = {"BEATRICE"}, t = "Good morrow, sweet Hero." },
    { r = {"HERO"}, t = "Why, how now? do you speak in the sick tune?" },
    { r = {"BEATRICE"}, t = "I am out of all other tune, methinks." },
    { r = {"MARGARET"}, t = "Clap’s into ‘Light o’ love’; that goes without a burden: do you sing it, and I’ll dance it." },
    { r = {"BEATRICE"}, t = "Ye, light o’ love with your heels! then, if your husband have stables enough, you’ll see he shall lack no barnes." },
    { r = {"MARGARET"}, t = "O illegitimate construction! I scorn that with my heels." },
    { r = {"BEATRICE"}, t = "’Tis almost five o’clock, cousin; ’tis time you were ready." },
    { r = {"BEATRICE"}, t = "By my troth, I am exceeding ill." },
    { r = {"BEATRICE"}, t = "Heigh-ho!" },
    { r = {"MARGARET"}, t = "For a hawk, a horse, or a husband?" },
    { r = {"BEATRICE"}, t = "For the letter that begins them all, H." },
    { r = {"MARGARET"}, t = "Well, and you be not turned Turk, there’s no more sailing by the star." },
    { r = {"BEATRICE"}, t = "What means the fool, trow?" },
    { r = {"MARGARET"}, t = "Nothing I; but God send everyone their heart’s desire!" },
    { r = {"HERO"}, t = "These gloves the Count sent me; they are an excellent perfume." },
    { r = {"BEATRICE"}, t = "I am stuffed, cousin, I cannot smell." },
    { r = {"MARGARET"}, t = "A maid, and stuffed! there’s goodly catching of cold." },
    { r = {"BEATRICE"}, t = "O, God help me!" },
    { r = {"BEATRICE"}, t = "God help me! how long have you professed apprehension?" },
    { r = {"MARGARET"}, t = "Ever since you left it. Doth not my wit become me rarely!" },
    { r = {"BEATRICE"}, t = "It is not seen enough, you should wear it in your cap." },
    { r = {"BEATRICE"}, t = "By my troth, I am sick." },
    { r = {"MARGARET"}, t = "Get you some of this distilled Carduus benedictus, and lay it to your heart: it is the only thing for a qualm." },
    { r = {"HERO"}, t = "There thou prick’st her with a thistle." },
    { r = {"BEATRICE"}, t = "Benedictus! why benedictus? you have some moral in this benedictus." },
    { r = {"MARGARET"}, t = "Moral! no, by my troth, I have no moral meaning; I meant, plain holy thistle." },
    { r = {"MARGARET"}, t = "You may think, perchance, that I think you are in love: nay, by’r Lady, I am not such a fool to think what I list; nor I list not to think what I can;" },
    { r = {"MARGARET"}, t = "nor, indeed, I cannot think, if I would think my heart out of thinking, that you are in love, or that you will be in love, or that you can be in love." },
    { r = {"MARGARET"}, t = "Yet Benedick was such another, and now is he become a man: he swore he would never marry; and yet now, in despite of his heart, he eats his meat without grudging: and how you may be converted, I know not;" },
    { r = {"MARGARET"}, t = "but methinks you look with your eyes as other women do." },
    { r = {"BEATRICE"}, t = "What pace is this that thy tongue keeps?" },
    { r = {"MARGARET"}, t = "Not a false gallop." },
    { d = "Re-enter Ursula" },
    { r = {"URSULA"}, t = "Madam, withdraw: the Prince, the Count, Signior Benedick, Don" },
    { r = {"URSULA"}, t = "John, and all the gallants of the town are come to fetch you to church." },
    { r = {"HERO"}, t = "Help to dress me, good coz, good Meg, good Ursula." },
    { d = "Exeunt" },
    { d = "Act 3, Scene 5. Another Room in Leonato’s House.", h = true },
    { d = "Enter Leonato and Dogberry and Verges" },
    { r = {"LEONATO"}, t = "What would you with me, honest neighbour?" },
    { r = {"DOGBERRY"}, t = "Marry, sir, I would have some confidence with you, that decerns you nearly." },
    { r = {"LEONATO"}, t = "Brief, I pray you; for you see it is a busy time with me." },
    { r = {"DOGBERRY"}, t = "Marry, this it is, sir." },
    { r = {"VERGES"}, t = "Yes, in truth it is, sir." },
    { r = {"LEONATO"}, t = "What is it, my good friends?" },
    { r = {"DOGBERRY"}, t = "Goodman Verges, sir, speaks a little off the matter: an old man, sir, and his wits are not so blunt as, God help, I would desire they were; but, in faith, honest as the skin between his brows." },
    { r = {"VERGES"}, t = "Yes, I thank God, I am as honest as any man living, that is an old man and no honester than I." },
    { r = {"DOGBERRY"}, t = "Comparisons are odorous: palabras, neighbour Verges." },
    { r = {"LEONATO"}, t = "Neighbours, you are tedious." },
    { r = {"DOGBERRY"}, t = "It pleases your worship to say so, but we are the poor Duke’s officers; but truly, for mine own part, if I were as tedious as a king, I could find in my heart to bestow it all of your worship." },
    { r = {"LEONATO"}, t = "All thy tediousness on me! ah?" },
    { r = {"DOGBERRY"}, t = "Yea, and ’twere a thousand pound more than ’tis; for I hear as good exclamation on your worship, as of any man in the city, and though I be but a poor man, I am glad to hear it." },
    { r = {"VERGES"}, t = "And so am I." },
    { r = {"LEONATO"}, t = "I would fain know what you have to say." },
    { r = {"VERGES"}, t = "Marry, sir, our watch tonight, excepting your worship’s presence, ha’ ta’en a couple of as arrant knaves as any in" },
    { r = {"VERGES"}, t = "Messina." },
    { r = {"DOGBERRY"}, t = "A good old man, sir; he will be talking; as they say, ‘when the age is in, the wit is out.’" },
    { r = {"DOGBERRY"}, t = "God help us! it is a world to see!" },
    { r = {"DOGBERRY"}, t = "Well said, i’ faith, neighbour Verges: well, God’s a good man; and two men ride of a horse, one must ride behind." },
    { r = {"DOGBERRY"}, t = "An honest soul, i’ faith, sir; by my troth he is, as ever broke bread; but God is to be worshipped: all men are not alike; alas! good neighbour." },
    { r = {"LEONATO"}, t = "Indeed, neighbour, he comes too short of you." },
    { r = {"DOGBERRY"}, t = "Gifts that God gives." },
    { r = {"LEONATO"}, t = "I must leave you." },
    { r = {"DOGBERRY"}, t = "One word, sir: our watch, sir, have indeed comprehended two aspicious persons, and we would have them this morning examined before your worship." },
    { r = {"LEONATO"}, t = "Take their examination yourself, and bring it me: I am now in great haste, as may appear unto you." },
    { r = {"DOGBERRY"}, t = "It shall be suffigance." },
    { r = {"LEONATO"}, t = "Drink some wine ere you go: fare you well." },
    { d = "Enter a Messenger" },
    { r = {"MESSENGER"}, t = "My lord, they stay for you to give your daughter to her husband." },
    { r = {"LEONATO"}, t = "I’ll wait upon them: I am ready." },
    { d = "Exeunt Leonato and Messenger" },
    { r = {"DOGBERRY"}, t = "Go, good partner, go get you to Francis Seacoal; bid him bring his pen and inkhorn to the gaol: we are now to examination these men." },
    { r = {"VERGES"}, t = "And we must do it wisely." },
    { r = {"DOGBERRY"}, t = "We will spare for no wit, I warrant you; here’s that shall drive some of them to a non-come: only get the learned writer to set down our excommunication, and meet me at the gaol." },
    { d = "Exeunt" },
    { d = "Act 4, Scene 1. The Inside of a Church.", h = true },
    { d = "Enter Don Pedro, Don John, Leonato, Friar Francis, Claudio, Benedick, Hero, Beatrice &c" },
    { r = {"LEONATO"}, t = "Come, Friar Francis, be brief: only to the plain form of marriage, and you shall recount their particular duties afterwards." },
    { r = {"FRIAR FRANCIS"}, t = "You come hither, my lord, to marry this lady?" },
    { r = {"CLAUDIO"}, t = "No." },
    { r = {"LEONATO"}, t = "To be married to her, friar; you come to marry her." },
    { r = {"FRIAR FRANCIS"}, t = "Lady, you come hither to be married to this Count?" },
    { r = {"HERO"}, t = "I do." },
    { r = {"FRIAR FRANCIS"}, t = "If either of you know any inward impediment, why you should not be conjoined, I charge you, on your souls, to utter it." },
    { r = {"CLAUDIO"}, t = "Know you any, Hero?" },
    { r = {"HERO"}, t = "None, my lord." },
    { r = {"FRIAR FRANCIS"}, t = "Know you any, Count?" },
    { r = {"LEONATO"}, t = "I dare make his answer; none." },
    { r = {"CLAUDIO"}, t = "O! what men dare do! what men may do! what men daily do, not knowing what they do!" },
    { r = {"BENEDICK"}, t = "How now!" },
    { r = {"BENEDICK"}, t = "Interjections?" },
    { r = {"BENEDICK"}, t = "Why then, some be of laughing, as ah! ha! he!" },
    { r = {"CLAUDIO"}, t = "Stand thee by, Friar. Father, by your leave:" },
    { r = {"CLAUDIO"}, t = "Will you with free and unconstrained soul" },
    { r = {"CLAUDIO"}, t = "Give me this maid, your daughter?" },
    { r = {"LEONATO"}, t = "As freely, son, as God did give her me." },
    { r = {"CLAUDIO"}, t = "And what have I to give you back whose worth" },
    { r = {"CLAUDIO"}, t = "May counterpoise this rich and precious gift?" },
    { r = {"DON PEDRO"}, t = "Nothing, unless you render her again." },
    { r = {"CLAUDIO"}, t = "Sweet Prince, you learn me noble thankfulness." },
    { r = {"CLAUDIO"}, t = "There, Leonato, take her back again:" },
    { r = {"CLAUDIO"}, t = "Give not this rotten orange to your friend;" },
    { r = {"CLAUDIO"}, t = "She’s but the sign and semblance of her honour." },
    { r = {"CLAUDIO"}, t = "Behold! how like a maid she blushes here." },
    { r = {"CLAUDIO"}, t = "O! what authority and show of truth" },
    { r = {"CLAUDIO"}, t = "Can cunning sin cover itself withal." },
    { r = {"CLAUDIO"}, t = "Comes not that blood as modest evidence" },
    { r = {"CLAUDIO"}, t = "To witness simple virtue? Would you not swear," },
    { r = {"CLAUDIO"}, t = "All you that see her, that she were a maid," },
    { r = {"CLAUDIO"}, t = "By these exterior shows? But she is none:" },
    { r = {"CLAUDIO"}, t = "She knows the heat of a luxurious bed;" },
    { r = {"CLAUDIO"}, t = "Her blush is guiltiness, not modesty." },
    { r = {"LEONATO"}, t = "What do you mean, my lord?" },
    { r = {"CLAUDIO"}, t = "Not to be married," },
    { r = {"CLAUDIO"}, t = "Not to knit my soul to an approved wanton." },
    { r = {"LEONATO"}, t = "Dear my lord, if you, in your own proof," },
    { r = {"LEONATO"}, t = "Have vanquish’d the resistance of her youth," },
    { r = {"LEONATO"}, t = "And made defeat of her virginity," },
    { r = {"CLAUDIO"}, t = "I know what you would say: if I have known her," },
    { r = {"CLAUDIO"}, t = "You will say she did embrace me as a husband," },
    { r = {"CLAUDIO"}, t = "And so extenuate the forehand sin: No, Leonato," },
    { r = {"CLAUDIO"}, t = "I never tempted her with word too large;" },
    { r = {"CLAUDIO"}, t = "But as a brother to his sister show’d" },
    { r = {"CLAUDIO"}, t = "Bashful sincerity and comely love." },
    { r = {"HERO"}, t = "And seem’d I ever otherwise to you?" },
    { r = {"CLAUDIO"}, t = "Out on thee! Seeming! I will write against it:" },
    { r = {"CLAUDIO"}, t = "You seem to me as Dian in her orb," },
    { r = {"CLAUDIO"}, t = "As chaste as is the bud ere it be blown;" },
    { r = {"CLAUDIO"}, t = "But you are more intemperate in your blood" },
    { r = {"CLAUDIO"}, t = "Than Venus, or those pamper’d animals" },
    { r = {"CLAUDIO"}, t = "That rage in savage sensuality." },
    { r = {"HERO"}, t = "Is my lord well, that he doth speak so wide?" },
    { r = {"LEONATO"}, t = "Sweet Prince, why speak not you?" },
    { r = {"DON PEDRO"}, t = "What should I speak?" },
    { r = {"DON PEDRO"}, t = "I stand dishonour’d, that have gone about" },
    { r = {"DON PEDRO"}, t = "To link my dear friend to a common stale." },
    { r = {"LEONATO"}, t = "Are these things spoken, or do I but dream?" },
    { r = {"DON JOHN"}, t = "Sir, they are spoken, and these things are true." },
    { r = {"BENEDICK"}, t = "This looks not like a nuptial." },
    { r = {"HERO"}, t = "True! O God!" },
    { r = {"CLAUDIO"}, t = "Leonato, stand I here?" },
    { r = {"CLAUDIO"}, t = "Is this the Prince? Is this the Prince’s brother?" },
    { r = {"CLAUDIO"}, t = "Is this face Hero’s? Are our eyes our own?" },
    { r = {"LEONATO"}, t = "All this is so; but what of this, my lord?" },
    { r = {"CLAUDIO"}, t = "Let me but move one question to your daughter," },
    { r = {"CLAUDIO"}, t = "And by that fatherly and kindly power" },
    { r = {"CLAUDIO"}, t = "That you have in her, bid her answer truly." },
    { r = {"LEONATO"}, t = "I charge thee do so, as thou art my child." },
    { r = {"HERO"}, t = "O, God defend me! how am I beset!" },
    { r = {"HERO"}, t = "What kind of catechizing call you this?" },
    { r = {"CLAUDIO"}, t = "To make you answer truly to your name." },
    { r = {"HERO"}, t = "Is it not Hero? Who can blot that name" },
    { r = {"HERO"}, t = "With any just reproach?" },
    { r = {"CLAUDIO"}, t = "Marry, that can Hero:" },
    { r = {"CLAUDIO"}, t = "Hero itself can blot out Hero’s virtue." },
    { r = {"CLAUDIO"}, t = "What man was he talk’d with you yesternight" },
    { r = {"CLAUDIO"}, t = "Out at your window, betwixt twelve and one?" },
    { r = {"CLAUDIO"}, t = "Now, if you are a maid, answer to this." },
    { r = {"HERO"}, t = "I talk’d with no man at that hour, my lord." },
    { r = {"DON PEDRO"}, t = "Why, then are you no maiden." },
    { r = {"DON PEDRO"}, t = "Leonato, I am sorry you must hear: upon my honour," },
    { r = {"DON PEDRO"}, t = "Myself, my brother, and this grieved Count," },
    { r = {"DON PEDRO"}, t = "Did see her, hear her, at that hour last night," },
    { r = {"DON PEDRO"}, t = "Talk with a ruffian at her chamber window;" },
    { r = {"DON PEDRO"}, t = "Who hath indeed, most like a liberal villain," },
    { r = {"DON PEDRO"}, t = "Confess’d the vile encounters they have had" },
    { r = {"DON PEDRO"}, t = "A thousand times in secret." },
    { r = {"DON JOHN"}, t = "Fie, fie! they are not to be nam’d, my lord," },
    { r = {"DON JOHN"}, t = "Not to be spoke of;" },
    { r = {"DON JOHN"}, t = "There is not chastity enough in language" },
    { r = {"DON JOHN"}, t = "Without offence to utter them. Thus, pretty lady," },
    { r = {"DON JOHN"}, t = "I am sorry for thy much misgovernment." },
    { r = {"CLAUDIO"}, t = "O Hero! what a Hero hadst thou been," },
    { r = {"CLAUDIO"}, t = "If half thy outward graces had been plac’d" },
    { r = {"CLAUDIO"}, t = "About thy thoughts and counsels of thy heart!" },
    { r = {"CLAUDIO"}, t = "But fare thee well, most foul, most fair! farewell," },
    { r = {"CLAUDIO"}, t = "Thou pure impiety, and impious purity!" },
    { r = {"CLAUDIO"}, t = "For thee I’ll lock up all the gates of love," },
    { r = {"CLAUDIO"}, t = "And on my eyelids shall conjecture hang," },
    { r = {"CLAUDIO"}, t = "To turn all beauty into thoughts of harm," },
    { r = {"CLAUDIO"}, t = "And never shall it more be gracious." },
    { r = {"LEONATO"}, t = "Hath no man’s dagger here a point for me?" },
    { r = {"HERO"}, d = "Hero swoons", e = "/lie" },
    { r = {"BEATRICE"}, t = "Why, how now, cousin! wherefore sink you down?" },
    { r = {"DON JOHN"}, t = "Come, let us go. These things, come thus to light," },
    { r = {"DON JOHN"}, t = "Smother her spirits up." },
    { d = "Exeunt Don Pedro, Don John and Claudio" },
    { r = {"BENEDICK"}, t = "How doth the lady?" },
    { r = {"BEATRICE"}, t = "Dead, I think! Help, uncle! Hero! why, Hero! Uncle! Signior" },
    { r = {"BEATRICE"}, t = "Benedick! Friar!" },
    { r = {"LEONATO"}, t = "O Fate! take not away thy heavy hand:" },
    { r = {"LEONATO"}, t = "Death is the fairest cover for her shame" },
    { r = {"LEONATO"}, t = "That may be wish’d for." },
    { r = {"BEATRICE"}, t = "How now, cousin Hero?" },
    { r = {"FRIAR FRANCIS"}, t = "Have comfort, lady." },
    { r = {"LEONATO"}, t = "Dost thou look up?" },
    { r = {"FRIAR FRANCIS"}, t = "Yea; wherefore should she not?" },
    { r = {"LEONATO"}, t = "Wherefore! Why, doth not every earthly thing" },
    { r = {"LEONATO"}, t = "Cry shame upon her? Could she here deny" },
    { r = {"LEONATO"}, t = "The story that is printed in her blood?" },
    { r = {"LEONATO"}, t = "Do not live, Hero; do not ope thine eyes;" },
    { r = {"LEONATO"}, t = "For, did I think thou wouldst not quickly die," },
    { r = {"LEONATO"}, t = "Thought I thy spirits were stronger than thy shames," },
    { r = {"LEONATO"}, t = "Myself would, on the rearward of reproaches," },
    { r = {"LEONATO"}, t = "Strike at thy life. Griev’d I, I had but one?" },
    { r = {"LEONATO"}, t = "Chid I for that at frugal Nature’s frame?" },
    { r = {"LEONATO"}, t = "O! one too much by thee. Why had I one?" },
    { r = {"LEONATO"}, t = "Why ever wast thou lovely in my eyes?" },
    { r = {"LEONATO"}, t = "Why had I not with charitable hand" },
    { r = {"LEONATO"}, t = "Took up a beggar’s issue at my gates," },
    { r = {"LEONATO"}, t = "Who smirched thus, and mir’d with infamy," },
    { r = {"LEONATO"}, t = "I might have said, ‘No part of it is mine;" },
    { r = {"LEONATO"}, t = "This shame derives itself from unknown loins?’" },
    { r = {"LEONATO"}, t = "But mine, and mine I lov’d, and mine I prais’d," },
    { r = {"LEONATO"}, t = "And mine that I was proud on, mine so much" },
    { r = {"LEONATO"}, t = "That I myself was to myself not mine," },
    { r = {"LEONATO"}, t = "Valuing of her; why, she—O! she is fallen" },
    { r = {"LEONATO"}, t = "Into a pit of ink, that the wide sea" },
    { r = {"LEONATO"}, t = "Hath drops too few to wash her clean again," },
    { r = {"LEONATO"}, t = "And salt too little which may season give" },
    { r = {"LEONATO"}, t = "To her foul tainted flesh." },
    { r = {"BENEDICK"}, t = "Sir, sir, be patient." },
    { r = {"BENEDICK"}, t = "For my part, I am so attir’d in wonder," },
    { r = {"BENEDICK"}, t = "I know not what to say." },
    { r = {"BEATRICE"}, t = "O! on my soul, my cousin is belied!" },
    { r = {"BENEDICK"}, t = "Lady, were you her bedfellow last night?" },
    { r = {"BEATRICE"}, t = "No, truly, not; although, until last night," },
    { r = {"BEATRICE"}, t = "I have this twelvemonth been her bedfellow." },
    { r = {"LEONATO"}, t = "Confirm’d, confirm’d! O! that is stronger made," },
    { r = {"LEONATO"}, t = "Which was before barr’d up with ribs of iron." },
    { r = {"LEONATO"}, t = "Would the two princes lie? and Claudio lie," },
    { r = {"LEONATO"}, t = "Who lov’d her so, that, speaking of her foulness," },
    { r = {"LEONATO"}, t = "Wash’d it with tears? Hence from her! let her die." },
    { r = {"FRIAR FRANCIS"}, t = "Hear me a little;" },
    { r = {"FRIAR FRANCIS"}, t = "For I have only been silent so long," },
    { r = {"FRIAR FRANCIS"}, t = "And given way unto this course of fortune," },
    { r = {"FRIAR FRANCIS"}, t = "By noting of the lady: I have mark’d" },
    { r = {"FRIAR FRANCIS"}, t = "A thousand blushing apparitions" },
    { r = {"FRIAR FRANCIS"}, t = "To start into her face; a thousand innocent shames" },
    { r = {"FRIAR FRANCIS"}, t = "In angel whiteness bear away those blushes;" },
    { r = {"FRIAR FRANCIS"}, t = "And in her eye there hath appear’d a fire," },
    { r = {"FRIAR FRANCIS"}, t = "To burn the errors that these princes hold" },
    { r = {"FRIAR FRANCIS"}, t = "Against her maiden truth. Call me a fool;" },
    { r = {"FRIAR FRANCIS"}, t = "Trust not my reading nor my observations," },
    { r = {"FRIAR FRANCIS"}, t = "Which with experimental seal doth warrant" },
    { r = {"FRIAR FRANCIS"}, t = "The tenure of my book; trust not my age," },
    { r = {"FRIAR FRANCIS"}, t = "My reverence, calling, nor divinity," },
    { r = {"FRIAR FRANCIS"}, t = "If this sweet lady lie not guiltless here" },
    { r = {"FRIAR FRANCIS"}, t = "Under some biting error." },
    { r = {"LEONATO"}, t = "Friar, it cannot be." },
    { r = {"LEONATO"}, t = "Thou seest that all the grace that she hath left" },
    { r = {"LEONATO"}, t = "Is that she will not add to her damnation" },
    { r = {"LEONATO"}, t = "A sin of perjury: she not denies it." },
    { r = {"LEONATO"}, t = "Why seek’st thou then to cover with excuse" },
    { r = {"LEONATO"}, t = "That which appears in proper nakedness?" },
    { r = {"FRIAR FRANCIS"}, t = "Lady, what man is he you are accus’d of?" },
    { r = {"HERO"}, t = "They know that do accuse me, I know none;" },
    { r = {"HERO"}, t = "If I know more of any man alive" },
    { r = {"HERO"}, t = "Than that which maiden modesty doth warrant," },
    { r = {"HERO"}, t = "Let all my sins lack mercy! O, my father!" },
    { r = {"HERO"}, t = "Prove you that any man with me convers’d" },
    { r = {"HERO"}, t = "At hours unmeet, or that I yesternight" },
    { r = {"HERO"}, t = "Maintain’d the change of words with any creature," },
    { r = {"HERO"}, t = "Refuse me, hate me, torture me to death." },
    { r = {"FRIAR FRANCIS"}, t = "There is some strange misprision in the princes." },
    { r = {"BENEDICK"}, t = "Two of them have the very bent of honour;" },
    { r = {"BENEDICK"}, t = "And if their wisdoms be misled in this," },
    { r = {"BENEDICK"}, t = "The practice of it lives in John the bastard," },
    { r = {"BENEDICK"}, t = "Whose spirits toil in frame of villainies." },
    { r = {"LEONATO"}, t = "I know not. If they speak but truth of her," },
    { r = {"LEONATO"}, t = "These hands shall tear her; if they wrong her honour," },
    { r = {"LEONATO"}, t = "The proudest of them shall well hear of it." },
    { r = {"LEONATO"}, t = "Time hath not yet so dried this blood of mine," },
    { r = {"LEONATO"}, t = "Nor age so eat up my invention," },
    { r = {"LEONATO"}, t = "Nor fortune made such havoc of my means," },
    { r = {"LEONATO"}, t = "Nor my bad life reft me so much of friends," },
    { r = {"LEONATO"}, t = "But they shall find, awak’d in such a kind," },
    { r = {"LEONATO"}, t = "Both strength of limb and policy of mind," },
    { r = {"LEONATO"}, t = "Ability in means and choice of friends," },
    { r = {"LEONATO"}, t = "To quit me of them throughly." },
    { r = {"FRIAR FRANCIS"}, t = "Pause awhile," },
    { r = {"FRIAR FRANCIS"}, t = "And let my counsel sway you in this case." },
    { r = {"FRIAR FRANCIS"}, t = "Your daughter here the princes left for dead;" },
    { r = {"FRIAR FRANCIS"}, t = "Let her awhile be secretly kept in," },
    { r = {"FRIAR FRANCIS"}, t = "And publish it that she is dead indeed:" },
    { r = {"FRIAR FRANCIS"}, t = "Maintain a mourning ostentation;" },
    { r = {"FRIAR FRANCIS"}, t = "And on your family’s old monument" },
    { r = {"FRIAR FRANCIS"}, t = "Hang mournful epitaphs and do all rites" },
    { r = {"FRIAR FRANCIS"}, t = "That appertain unto a burial." },
    { r = {"LEONATO"}, t = "What shall become of this? What will this do?" },
    { r = {"FRIAR FRANCIS"}, t = "Marry, this well carried shall on her behalf" },
    { r = {"FRIAR FRANCIS"}, t = "Change slander to remorse; that is some good." },
    { r = {"FRIAR FRANCIS"}, t = "But not for that dream I on this strange course," },
    { r = {"FRIAR FRANCIS"}, t = "But on this travail look for greater birth." },
    { r = {"FRIAR FRANCIS"}, t = "She dying, as it must be so maintain’d," },
    { r = {"FRIAR FRANCIS"}, t = "Upon the instant that she was accus’d," },
    { r = {"FRIAR FRANCIS"}, t = "Shall be lamented, pitied and excus’d" },
    { r = {"FRIAR FRANCIS"}, t = "Of every hearer; for it so falls out" },
    { r = {"FRIAR FRANCIS"}, t = "That what we have we prize not to the worth" },
    { r = {"FRIAR FRANCIS"}, t = "Whiles we enjoy it, but being lack’d and lost," },
    { r = {"FRIAR FRANCIS"}, t = "Why, then we rack the value, then we find" },
    { r = {"FRIAR FRANCIS"}, t = "The virtue that possession would not show us" },
    { r = {"FRIAR FRANCIS"}, t = "Whiles it was ours. So will it fare with Claudio:" },
    { r = {"FRIAR FRANCIS"}, t = "When he shall hear she died upon his words," },
    { r = {"FRIAR FRANCIS"}, t = "The idea of her life shall sweetly creep" },
    { r = {"FRIAR FRANCIS"}, t = "Into his study of imagination," },
    { r = {"FRIAR FRANCIS"}, t = "And every lovely organ of her life" },
    { r = {"FRIAR FRANCIS"}, t = "Shall come apparell’d in more precious habit," },
    { r = {"FRIAR FRANCIS"}, t = "More moving, delicate, and full of life" },
    { r = {"FRIAR FRANCIS"}, t = "Into the eye and prospect of his soul," },
    { r = {"FRIAR FRANCIS"}, t = "Than when she liv’d indeed: then shall he mourn,—" },
    { r = {"FRIAR FRANCIS"}, t = "If ever love had interest in his liver,—" },
    { r = {"FRIAR FRANCIS"}, t = "And wish he had not so accused her," },
    { r = {"FRIAR FRANCIS"}, t = "No, though he thought his accusation true." },
    { r = {"FRIAR FRANCIS"}, t = "Let this be so, and doubt not but success" },
    { r = {"FRIAR FRANCIS"}, t = "Will fashion the event in better shape" },
    { r = {"FRIAR FRANCIS"}, t = "Than I can lay it down in likelihood." },
    { r = {"FRIAR FRANCIS"}, t = "But if all aim but this be levell’d false," },
    { r = {"FRIAR FRANCIS"}, t = "The supposition of the lady’s death" },
    { r = {"FRIAR FRANCIS"}, t = "Will quench the wonder of her infamy:" },
    { r = {"FRIAR FRANCIS"}, t = "And if it sort not well, you may conceal her,—" },
    { r = {"FRIAR FRANCIS"}, t = "As best befits her wounded reputation,—" },
    { r = {"FRIAR FRANCIS"}, t = "In some reclusive and religious life," },
    { r = {"FRIAR FRANCIS"}, t = "Out of all eyes, tongues, minds, and injuries." },
    { r = {"BENEDICK"}, t = "Signior Leonato, let the friar advise you:" },
    { r = {"BENEDICK"}, t = "And though you know my inwardness and love" },
    { r = {"BENEDICK"}, t = "Is very much unto the Prince and Claudio," },
    { r = {"BENEDICK"}, t = "Yet, by mine honour, I will deal in this" },
    { r = {"BENEDICK"}, t = "As secretly and justly as your soul" },
    { r = {"BENEDICK"}, t = "Should with your body." },
    { r = {"LEONATO"}, t = "Being that I flow in grief," },
    { r = {"LEONATO"}, t = "The smallest twine may lead me." },
    { r = {"FRIAR FRANCIS"}, t = "’Tis well consented: presently away;" },
    { r = {"FRIAR FRANCIS"}, t = "For to strange sores strangely they strain the cure." },
    { r = {"FRIAR FRANCIS"}, t = "Come, lady, die to live: this wedding day" },
    { r = {"FRIAR FRANCIS"}, t = "Perhaps is but prolong’d: have patience and endure." },
    { d = "Exeunt Friar, Hero and Leonato" },
    { r = {"BENEDICK"}, t = "Lady Beatrice, have you wept all this while?" },
    { r = {"BEATRICE"}, t = "Yea, and I will weep a while longer." },
    { r = {"BENEDICK"}, t = "I will not desire that." },
    { r = {"BEATRICE"}, t = "You have no reason; I do it freely." },
    { r = {"BENEDICK"}, t = "Surely I do believe your fair cousin is wronged." },
    { r = {"BEATRICE"}, t = "Ah! how much might the man deserve of me that would right her." },
    { r = {"BENEDICK"}, t = "Is there any way to show such friendship?" },
    { r = {"BEATRICE"}, t = "A very even way, but no such friend." },
    { r = {"BENEDICK"}, t = "May a man do it?" },
    { r = {"BEATRICE"}, t = "It is a man’s office, but not yours." },
    { r = {"BENEDICK"}, t = "I do love nothing in the world so well as you: is not that strange?" },
    { r = {"BEATRICE"}, t = "As strange as the thing I know not." },
    { r = {"BEATRICE"}, t = "It were as possible for me to say I loved nothing so well as you; but believe me not, and yet I lie not; I confess nothing, nor I deny nothing." },
    { r = {"BEATRICE"}, t = "I am sorry for my cousin." },
    { r = {"BENEDICK"}, t = "By my sword, Beatrice, thou lovest me." },
    { r = {"BEATRICE"}, t = "Do not swear by it, and eat it." },
    { r = {"BENEDICK"}, t = "I will swear by it that you love me; and I will make him eat it that says I love not you." },
    { r = {"BEATRICE"}, t = "Will you not eat your word?" },
    { r = {"BENEDICK"}, t = "With no sauce that can be devised to it. I protest I love thee." },
    { r = {"BEATRICE"}, t = "Why then, God forgive me!" },
    { r = {"BENEDICK"}, t = "What offence, sweet Beatrice?" },
    { r = {"BEATRICE"}, t = "You have stayed me in a happy hour: I was about to protest I loved you." },
    { r = {"BENEDICK"}, t = "And do it with all thy heart." },
    { r = {"BEATRICE"}, t = "I love you with so much of my heart that none is left to protest." },
    { r = {"BENEDICK"}, t = "Come, bid me do anything for thee." },
    { r = {"BEATRICE"}, t = "Kill Claudio." },
    { r = {"BENEDICK"}, t = "Ha! not for the wide world." },
    { r = {"BEATRICE"}, t = "You kill me to deny it. Farewell." },
    { r = {"BENEDICK"}, t = "Tarry, sweet Beatrice." },
    { r = {"BEATRICE"}, t = "I am gone, though I am here: there is no love in you: nay, I pray you, let me go." },
    { r = {"BENEDICK"}, t = "Beatrice," },
    { r = {"BEATRICE"}, t = "In faith, I will go." },
    { r = {"BENEDICK"}, t = "We’ll be friends first." },
    { r = {"BEATRICE"}, t = "You dare easier be friends with me than fight with mine enemy." },
    { r = {"BENEDICK"}, t = "Is Claudio thine enemy?" },
    { r = {"BEATRICE"}, t = "Is he not approved in the height a villain, that hath slandered, scorned, dishonoured my kinswoman?" },
    { r = {"BEATRICE"}, t = "O! that I were a man." },
    { r = {"BEATRICE"}, t = "What! bear her in hand until they come to take hands, and then, with public accusation, uncovered slander, unmitigated rancour,—O God, that I were a man!" },
    { r = {"BEATRICE"}, t = "I would eat his heart in the market-place." },
    { r = {"BENEDICK"}, t = "Hear me, Beatrice," },
    { r = {"BEATRICE"}, t = "Talk with a man out at a window! a proper saying!" },
    { r = {"BENEDICK"}, t = "Nay, but Beatrice," },
    { r = {"BEATRICE"}, t = "Sweet Hero! she is wronged, she is slandered, she is undone." },
    { r = {"BENEDICK"}, t = "Beat" },
    { r = {"BEATRICE"}, t = "Princes and Counties! Surely, a princely testimony, a goodly" },
    { r = {"BEATRICE"}, t = "Count Comfect; a sweet gallant, surely!" },
    { r = {"BEATRICE"}, t = "O! that I were a man for his sake, or that I had any friend would be a man for my sake!" },
    { r = {"BEATRICE"}, t = "But manhood is melted into curtsies, valour into compliment, and men are only turned into tongue, and trim ones too: he is now as valiant as Hercules, that only tells a lie and swears it." },
    { r = {"BEATRICE"}, t = "I cannot be a man with wishing, therefore I will die a woman with grieving." },
    { r = {"BENEDICK"}, t = "Tarry, good Beatrice. By this hand, I love thee." },
    { r = {"BEATRICE"}, t = "Use it for my love some other way than swearing by it." },
    { r = {"BENEDICK"}, t = "Think you in your soul the Count Claudio hath wronged Hero?" },
    { r = {"BEATRICE"}, t = "Yea, as sure is I have a thought or a soul." },
    { r = {"BENEDICK"}, t = "Enough!" },
    { r = {"BENEDICK"}, t = "I am engaged, I will challenge him." },
    { r = {"BENEDICK"}, t = "I will kiss your hand, and so leave you." },
    { r = {"BENEDICK"}, t = "By this hand, Claudio shall render me a dear account." },
    { r = {"BENEDICK"}, t = "As you hear of me, so think of me." },
    { r = {"BENEDICK"}, t = "Go, comfort your cousin: I must say she is dead; and so, farewell." },
    { d = "Exeunt" },
    { d = "Act 4, Scene 2. A Prison.", h = true },
    { d = "Enter Dogberry, Verges, and Sexton, in gowns; and the Watch, with Conrade and Borachio" },
    { r = {"DOGBERRY"}, t = "Is our whole dissembly appeared?" },
    { r = {"VERGES"}, t = "O! a stool and a cushion for the sexton." },
    { r = {"SEXTON"}, t = "Which be the malefactors?" },
    { r = {"DOGBERRY"}, t = "Marry, that am I and my partner." },
    { r = {"VERGES"}, t = "Nay, that’s certain: we have the exhibition to examine." },
    { r = {"SEXTON"}, t = "But which are the offenders that are to be examined? let them come before Master Constable." },
    { r = {"DOGBERRY"}, t = "Yea, marry, let them come before me. What is your name, friend?" },
    { r = {"BORACHIO"}, t = "Borachio." },
    { r = {"DOGBERRY"}, t = "Pray write down Borachio. Yours, sirrah?" },
    { r = {"CONRADE"}, t = "I am a gentleman, sir, and my name is Conrade." },
    { r = {"DOGBERRY"}, t = "Write down Master gentleman Conrade. Masters, do you serve God?" },
    { r = {"BORACHIO", "CONRADE"}, t = "Yea, sir, we hope." },
    { r = {"DOGBERRY"}, t = "Write down that they hope they serve God: and write God first; for God defend but God should go before such villains!" },
    { r = {"DOGBERRY"}, t = "Masters, it is proved already that you are little better than false knaves, and it will go near to be thought so shortly." },
    { r = {"DOGBERRY"}, t = "How answer you for yourselves?" },
    { r = {"CONRADE"}, t = "Marry, sir, we say we are none." },
    { r = {"DOGBERRY"}, t = "A marvellous witty fellow, I assure you; but I will go about with him." },
    { r = {"DOGBERRY"}, t = "Come you hither, sirrah; a word in your ear: sir, I say to you, it is thought you are false knaves." },
    { r = {"BORACHIO"}, t = "Sir, I say to you we are none." },
    { r = {"DOGBERRY"}, t = "Well, stand aside." },
    { r = {"DOGBERRY"}, t = "Fore God, they are both in a tale." },
    { r = {"DOGBERRY"}, t = "Have you writ down, that they are none?" },
    { r = {"SEXTON"}, t = "Master Constable, you go not the way to examine: you must call forth the watch that are their accusers." },
    { r = {"DOGBERRY"}, t = "Yea, marry, that’s the eftest way. Let the watch come forth." },
    { r = {"DOGBERRY"}, t = "Masters, I charge you, in the Prince’s name, accuse these men." },
    { r = {"FIRST WATCH"}, t = "This man said, sir, that Don John, the Prince’s brother, was a villain." },
    { r = {"DOGBERRY"}, t = "Write down Prince John a villain." },
    { r = {"DOGBERRY"}, t = "Why, this is flat perjury, to call a Prince’s brother villain." },
    { r = {"BORACHIO"}, t = "Master Constable," },
    { r = {"DOGBERRY"}, t = "Pray thee, fellow, peace: I do not like thy look, I promise thee." },
    { r = {"SEXTON"}, t = "What heard you him say else?" },
    { r = {"SECOND WATCH"}, t = "Marry, that he had received a thousand ducats of Don John for accusing the Lady Hero wrongfully." },
    { r = {"DOGBERRY"}, t = "Flat burglary as ever was committed." },
    { r = {"VERGES"}, t = "Yea, by the mass, that it is." },
    { r = {"SEXTON"}, t = "What else, fellow?" },
    { r = {"FIRST WATCH"}, t = "And that Count Claudio did mean, upon his words, to disgrace" },
    { r = {"FIRST WATCH"}, t = "Hero before the whole assembly, and not marry her." },
    { r = {"DOGBERRY"}, t = "O villain! thou wilt be condemned into everlasting redemption for this." },
    { r = {"SEXTON"}, t = "What else?" },
    { r = {"SECOND WATCH"}, t = "This is all." },
    { r = {"SEXTON"}, t = "And this is more, masters, than you can deny." },
    { r = {"SEXTON"}, t = "Prince John is this morning secretly stolen away: Hero was in this manner accused, in this manner refused, and, upon the grief of this, suddenly died." },
    { r = {"SEXTON"}, t = "Master Constable, let these men be bound, and brought to Leonato’s: I will go before and show him their examination." },
    { d = "Exit" },
    { r = {"DOGBERRY"}, t = "Come, let them be opinioned." },
    { r = {"VERGES"}, t = "Let them be in the hands" },
    { r = {"CONRADE"}, t = "Off, coxcomb!" },
    { r = {"DOGBERRY"}, t = "God’s my life! where’s the sexton? let him write down the Prince’s officer coxcomb." },
    { r = {"DOGBERRY"}, t = "Come, bind them." },
    { r = {"DOGBERRY"}, t = "Thou naughty varlet!" },
    { r = {"CONRADE"}, t = "Away! you are an ass; you are an ass." },
    { r = {"DOGBERRY"}, t = "Dost thou not suspect my place? Dost thou not suspect my years?" },
    { r = {"DOGBERRY"}, t = "O that he were here to write me down an ass! but, masters, remember that I am an ass; though it be not written down, yet forget not that I am an ass." },
    { r = {"DOGBERRY"}, t = "No, thou villain, thou art full of piety, as shall be proved upon thee by good witness." },
    { r = {"DOGBERRY"}, t = "I am a wise fellow; and, which is more, an officer; and, which is more, a householder; and, which is more, as pretty a piece of flesh as any in Messina; and one that knows the law, go to; and a rich fellow enough, go to;" },
    { r = {"DOGBERRY"}, t = "and a fellow that hath had losses; and one that hath two gowns, and everything handsome about him." },
    { r = {"DOGBERRY"}, t = "Bring him away." },
    { r = {"DOGBERRY"}, t = "O that I had been writ down an ass!" },
    { d = "Exeunt" },
    { d = "Act 5, Scene 1. Before Leonato’s House.", h = true },
    { d = "Enter Leonato and Antonio" },
    { r = {"ANTONIO"}, t = "If you go on thus, you will kill yourself" },
    { r = {"ANTONIO"}, t = "And ’tis not wisdom thus to second grief" },
    { r = {"ANTONIO"}, t = "Against yourself." },
    { r = {"LEONATO"}, t = "I pray thee, cease thy counsel," },
    { r = {"LEONATO"}, t = "Which falls into mine ears as profitless" },
    { r = {"LEONATO"}, t = "As water in a sieve: give not me counsel;" },
    { r = {"LEONATO"}, t = "Nor let no comforter delight mine ear" },
    { r = {"LEONATO"}, t = "But such a one whose wrongs do suit with mine:" },
    { r = {"LEONATO"}, t = "Bring me a father that so lov’d his child," },
    { r = {"LEONATO"}, t = "Whose joy of her is overwhelm’d like mine," },
    { r = {"LEONATO"}, t = "And bid him speak of patience;" },
    { r = {"LEONATO"}, t = "Measure his woe the length and breadth of mine," },
    { r = {"LEONATO"}, t = "And let it answer every strain for strain," },
    { r = {"LEONATO"}, t = "As thus for thus and such a grief for such," },
    { r = {"LEONATO"}, t = "In every lineament, branch, shape, and form:" },
    { r = {"LEONATO"}, t = "If such a one will smile, and stroke his beard;" },
    { r = {"LEONATO"}, t = "Bid sorrow wag, cry ‘hem’ when he should groan," },
    { r = {"LEONATO"}, t = "Patch grief with proverbs; make misfortune drunk" },
    { r = {"LEONATO"}, t = "With candle-wasters; bring him yet to me," },
    { r = {"LEONATO"}, t = "And I of him will gather patience." },
    { r = {"LEONATO"}, t = "But there is no such man; for, brother, men" },
    { r = {"LEONATO"}, t = "Can counsel and speak comfort to that grief" },
    { r = {"LEONATO"}, t = "Which they themselves not feel; but, tasting it," },
    { r = {"LEONATO"}, t = "Their counsel turns to passion, which before" },
    { r = {"LEONATO"}, t = "Would give preceptial medicine to rage," },
    { r = {"LEONATO"}, t = "Fetter strong madness in a silken thread," },
    { r = {"LEONATO"}, t = "Charm ache with air and agony with words." },
    { r = {"LEONATO"}, t = "No, no; ’tis all men’s office to speak patience" },
    { r = {"LEONATO"}, t = "To those that wring under the load of sorrow," },
    { r = {"LEONATO"}, t = "But no man’s virtue nor sufficiency" },
    { r = {"LEONATO"}, t = "To be so moral when he shall endure" },
    { r = {"LEONATO"}, t = "The like himself. Therefore give me no counsel:" },
    { r = {"LEONATO"}, t = "My griefs cry louder than advertisement." },
    { r = {"ANTONIO"}, t = "Therein do men from children nothing differ." },
    { r = {"LEONATO"}, t = "I pray thee peace! I will be flesh and blood;" },
    { r = {"LEONATO"}, t = "For there was never yet philosopher" },
    { r = {"LEONATO"}, t = "That could endure the toothache patiently," },
    { r = {"LEONATO"}, t = "However they have writ the style of gods" },
    { r = {"LEONATO"}, t = "And made a push at chance and sufferance." },
    { r = {"ANTONIO"}, t = "Yet bend not all the harm upon yourself;" },
    { r = {"ANTONIO"}, t = "Make those that do offend you suffer too." },
    { r = {"LEONATO"}, t = "There thou speak’st reason: nay, I will do so." },
    { r = {"LEONATO"}, t = "My soul doth tell me Hero is belied;" },
    { r = {"LEONATO"}, t = "And that shall Claudio know; so shall the Prince," },
    { r = {"LEONATO"}, t = "And all of them that thus dishonour her." },
    { r = {"ANTONIO"}, t = "Here comes the Prince and Claudio hastily." },
    { d = "Enter Don Pedro and Claudio" },
    { r = {"DON PEDRO"}, t = "Good den, good den." },
    { r = {"CLAUDIO"}, t = "Good day to both of you." },
    { r = {"LEONATO"}, t = "Hear you, my lords," },
    { r = {"DON PEDRO"}, t = "We have some haste, Leonato." },
    { r = {"LEONATO"}, t = "Some haste, my lord! well, fare you well, my lord:" },
    { r = {"LEONATO"}, t = "Are you so hasty now?—well, all is one." },
    { r = {"DON PEDRO"}, t = "Nay, do not quarrel with us, good old man." },
    { r = {"ANTONIO"}, t = "If he could right himself with quarrelling," },
    { r = {"ANTONIO"}, t = "Some of us would lie low." },
    { r = {"CLAUDIO"}, t = "Who wrongs him?" },
    { r = {"LEONATO"}, t = "Marry, thou dost wrong me; thou dissembler, thou." },
    { r = {"LEONATO"}, t = "Nay, never lay thy hand upon thy sword;" },
    { r = {"LEONATO"}, t = "I fear thee not." },
    { r = {"CLAUDIO"}, t = "Marry, beshrew my hand," },
    { r = {"CLAUDIO"}, t = "If it should give your age such cause of fear." },
    { r = {"CLAUDIO"}, t = "In faith, my hand meant nothing to my sword." },
    { r = {"LEONATO"}, t = "Tush, tush, man! never fleer and jest at me:" },
    { r = {"LEONATO"}, t = "I speak not like a dotard nor a fool," },
    { r = {"LEONATO"}, t = "As, under privilege of age, to brag" },
    { r = {"LEONATO"}, t = "What I have done being young, or what would do," },
    { r = {"LEONATO"}, t = "Were I not old. Know, Claudio, to thy head," },
    { r = {"LEONATO"}, t = "Thou hast so wrong’d mine innocent child and me" },
    { r = {"LEONATO"}, t = "That I am forc’d to lay my reverence by," },
    { r = {"LEONATO"}, t = "And, with grey hairs and bruise of many days," },
    { r = {"LEONATO"}, t = "Do challenge thee to trial of a man." },
    { r = {"LEONATO"}, t = "I say thou hast belied mine innocent child:" },
    { r = {"LEONATO"}, t = "Thy slander hath gone through and through her heart," },
    { r = {"LEONATO"}, t = "And she lies buried with her ancestors;" },
    { r = {"LEONATO"}, t = "O! in a tomb where never scandal slept," },
    { r = {"LEONATO"}, t = "Save this of hers, fram’d by thy villainy!" },
    { r = {"CLAUDIO"}, t = "My villainy?" },
    { r = {"LEONATO"}, t = "Thine, Claudio; thine, I say." },
    { r = {"DON PEDRO"}, t = "You say not right, old man." },
    { r = {"LEONATO"}, t = "My lord, my lord," },
    { r = {"LEONATO"}, t = "I’ll prove it on his body, if he dare," },
    { r = {"LEONATO"}, t = "Despite his nice fence and his active practice," },
    { r = {"LEONATO"}, t = "His May of youth and bloom of lustihood." },
    { r = {"CLAUDIO"}, t = "Away! I will not have to do with you." },
    { r = {"LEONATO"}, t = "Canst thou so daff me? Thou hast kill’d my child;" },
    { r = {"LEONATO"}, t = "If thou kill’st me, boy, thou shalt kill a man." },
    { r = {"ANTONIO"}, t = "He shall kill two of us, and men indeed:" },
    { r = {"ANTONIO"}, t = "But that’s no matter; let him kill one first:" },
    { r = {"ANTONIO"}, t = "Win me and wear me; let him answer me." },
    { r = {"ANTONIO"}, t = "Come, follow me, boy; come, sir boy, come, follow me." },
    { r = {"ANTONIO"}, t = "Sir boy, I’ll whip you from your foining fence;" },
    { r = {"ANTONIO"}, t = "Nay, as I am a gentleman, I will." },
    { r = {"LEONATO"}, t = "Brother," },
    { r = {"ANTONIO"}, t = "Content yourself. God knows I lov’d my niece;" },
    { r = {"ANTONIO"}, t = "And she is dead, slander’d to death by villains," },
    { r = {"ANTONIO"}, t = "That dare as well answer a man indeed" },
    { r = {"ANTONIO"}, t = "As I dare take a serpent by the tongue." },
    { r = {"ANTONIO"}, t = "Boys, apes, braggarts, Jacks, milksops!" },
    { r = {"LEONATO"}, t = "Brother Anthony," },
    { r = {"ANTONIO"}, t = "Hold you content. What, man! I know them, yea," },
    { r = {"ANTONIO"}, t = "And what they weigh, even to the utmost scruple," },
    { r = {"ANTONIO"}, t = "Scambling, out-facing, fashion-monging boys," },
    { r = {"ANTONIO"}, t = "That lie and cog and flout, deprave and slander," },
    { r = {"ANTONIO"}, t = "Go antickly, show outward hideousness," },
    { r = {"ANTONIO"}, t = "And speak off half a dozen dangerous words," },
    { r = {"ANTONIO"}, t = "How they might hurt their enemies, if they durst;" },
    { r = {"ANTONIO"}, t = "And this is all!" },
    { r = {"LEONATO"}, t = "But, brother Anthony," },
    { r = {"ANTONIO"}, t = "Come, ’tis no matter:" },
    { r = {"ANTONIO"}, t = "Do not you meddle, let me deal in this." },
    { r = {"DON PEDRO"}, t = "Gentlemen both, we will not wake your patience." },
    { r = {"DON PEDRO"}, t = "My heart is sorry for your daughter’s death;" },
    { r = {"DON PEDRO"}, t = "But, on my honour, she was charg’d with nothing" },
    { r = {"DON PEDRO"}, t = "But what was true and very full of proof." },
    { r = {"LEONATO"}, t = "My lord, my lord" },
    { r = {"DON PEDRO"}, t = "I will not hear you." },
    { r = {"LEONATO"}, t = "No? Come, brother, away. I will be heard." },
    { r = {"ANTONIO"}, t = "And shall, or some of us will smart for it." },
    { d = "Exeunt Leonato and Antonio" },
    { d = "Enter Benedick" },
    { r = {"DON PEDRO"}, t = "See, see; here comes the man we went to seek." },
    { r = {"CLAUDIO"}, t = "Now, signior, what news?" },
    { r = {"BENEDICK"}, t = "Good day, my lord." },
    { r = {"DON PEDRO"}, t = "Welcome, signior: you are almost come to part almost a fray." },
    { r = {"CLAUDIO"}, t = "We had like to have had our two noses snapped off with two old men without teeth." },
    { r = {"DON PEDRO"}, t = "Leonato and his brother." },
    { r = {"DON PEDRO"}, t = "What think’st thou?" },
    { r = {"DON PEDRO"}, t = "Had we fought, I doubt we should have been too young for them." },
    { r = {"BENEDICK"}, t = "In a false quarrel there is no true valour. I came to seek you both." },
    { r = {"CLAUDIO"}, t = "We have been up and down to seek thee; for we are high-proof melancholy, and would fain have it beaten away." },
    { r = {"CLAUDIO"}, t = "Wilt thou use thy wit?" },
    { r = {"BENEDICK"}, t = "It is in my scabbard; shall I draw it?" },
    { r = {"DON PEDRO"}, t = "Dost thou wear thy wit by thy side?" },
    { r = {"CLAUDIO"}, t = "Never any did so, though very many have been beside their wit." },
    { r = {"CLAUDIO"}, t = "I will bid thee draw, as we do the minstrels; draw, to pleasure us." },
    { r = {"DON PEDRO"}, t = "As I am an honest man, he looks pale. Art thou sick, or angry?" },
    { r = {"CLAUDIO"}, t = "What, courage, man!" },
    { r = {"CLAUDIO"}, t = "What though care killed a cat, thou hast mettle enough in thee to kill care." },
    { r = {"BENEDICK"}, t = "Sir, I shall meet your wit in the career, and you charge it against me." },
    { r = {"BENEDICK"}, t = "I pray you choose another subject." },
    { r = {"CLAUDIO"}, t = "Nay then, give him another staff: this last was broke cross." },
    { r = {"DON PEDRO"}, t = "By this light, he changes more and more: I think he be angry indeed." },
    { r = {"CLAUDIO"}, t = "If he be, he knows how to turn his girdle." },
    { r = {"BENEDICK"}, t = "Shall I speak a word in your ear?" },
    { r = {"CLAUDIO"}, t = "God bless me from a challenge!" },
    { r = {"BENEDICK"}, t = "You are a villain, I jest not: I will make it good how you dare, with what you dare, and when you dare.", d = "Aside to Claudio" },
    { r = {"BENEDICK"}, t = "Do me right, or I will protest your cowardice." },
    { r = {"BENEDICK"}, t = "You have killed a sweet lady, and her death shall fall heavy on you." },
    { r = {"BENEDICK"}, t = "Let me hear from you." },
    { r = {"CLAUDIO"}, t = "Well I will meet you, so I may have good cheer." },
    { r = {"DON PEDRO"}, t = "What, a feast, a feast?" },
    { r = {"CLAUDIO"}, t = "I’ faith, I thank him; he hath bid me to a calf’s-head and a capon, the which if I do not carve most curiously, say my knife’s naught." },
    { r = {"CLAUDIO"}, t = "Shall I not find a woodcock too?" },
    { r = {"BENEDICK"}, t = "Sir, your wit ambles well; it goes easily." },
    { r = {"DON PEDRO"}, t = "I’ll tell thee how Beatrice praised thy wit the other day." },
    { r = {"DON PEDRO"}, t = "I said, thou hadst a fine wit." },
    { r = {"DON PEDRO"}, t = "‘True,’ says she, ‘a fine little one.’" },
    { r = {"DON PEDRO"}, t = "‘No,’ said I, ‘a great wit.’" },
    { r = {"DON PEDRO"}, t = "‘Right,’ said she, ‘a great gross one.’" },
    { r = {"DON PEDRO"}, t = "‘Nay,’ said I, ‘a good wit.’" },
    { r = {"DON PEDRO"}, t = "‘Just,’ said she, ‘it hurts nobody.’" },
    { r = {"DON PEDRO"}, t = "‘Nay,’ said I, ‘the gentleman is wise.’" },
    { r = {"DON PEDRO"}, t = "‘Certain,’ said she, ‘a wise gentleman.’" },
    { r = {"DON PEDRO"}, t = "‘Nay,’ said I, ‘he hath the tongues.’" },
    { r = {"DON PEDRO"}, t = "‘That I believe’ said she, ‘for he swore a thing to me on Monday night, which he forswore on Tuesday morning: there’s a double tongue; there’s two tongues.’" },
    { r = {"DON PEDRO"}, t = "Thus did she, an hour together, trans-shape thy particular virtues; yet at last she concluded with a sigh, thou wast the properest man in Italy." },
    { r = {"CLAUDIO"}, t = "For the which she wept heartily and said she cared not." },
    { r = {"DON PEDRO"}, t = "Yea, that she did; but yet, for all that, an if she did not hate him deadly, she would love him dearly." },
    { r = {"DON PEDRO"}, t = "The old man’s daughter told us all." },
    { r = {"CLAUDIO"}, t = "All, all; and moreover, God saw him when he was hid in the garden." },
    { r = {"DON PEDRO"}, t = "But when shall we set the savage bull’s horns on the sensible Benedick’s head?" },
    { r = {"CLAUDIO"}, t = "Yea, and text underneath, ‘Here dwells Benedick the married man!’" },
    { r = {"BENEDICK"}, t = "Fare you well, boy: you know my mind." },
    { r = {"BENEDICK"}, t = "I will leave you now to your gossip-like humour; you break jests as braggarts do their blades, which, God be thanked, hurt not." },
    { r = {"BENEDICK"}, t = "My lord, for your many courtesies I thank you: I must discontinue your company." },
    { r = {"BENEDICK"}, t = "Your brother the bastard is fled from Messina: you have, among you, killed a sweet and innocent lady." },
    { r = {"BENEDICK"}, t = "For my Lord Lack-beard there, he and I shall meet; and till then, peace be with him." },
    { d = "Exit" },
    { r = {"DON PEDRO"}, t = "He is in earnest." },
    { r = {"CLAUDIO"}, t = "In most profound earnest; and, I’ll warrant you, for the love of Beatrice." },
    { r = {"DON PEDRO"}, t = "And hath challenged thee?" },
    { r = {"CLAUDIO"}, t = "Most sincerely." },
    { r = {"DON PEDRO"}, t = "What a pretty thing man is when he goes in his doublet and hose and leaves off his wit!" },
    { r = {"CLAUDIO"}, t = "He is then a giant to an ape; but then is an ape a doctor to such a man." },
    { r = {"DON PEDRO"}, t = "But, soft you; let me be: pluck up, my heart, and be sad!" },
    { r = {"DON PEDRO"}, t = "Did he not say my brother was fled?" },
    { d = "Enter Dogberry, Verges,  and the Watch, with Conrade and Borachio" },
    { r = {"DOGBERRY"}, t = "Come you, sir: if justice cannot tame you, she shall ne’er weigh more reasons in her balance." },
    { r = {"DOGBERRY"}, t = "Nay, an you be a cursing hypocrite once, you must be looked to." },
    { r = {"DON PEDRO"}, t = "How now! two of my brother’s men bound! Borachio, one!" },
    { r = {"CLAUDIO"}, t = "Hearken after their offence, my lord." },
    { r = {"DON PEDRO"}, t = "Officers, what offence have these men done?" },
    { r = {"DOGBERRY"}, t = "Marry, sir, they have committed false report; moreover, they have spoken untruths; secondarily, they are slanders; sixth and lastly, they have belied a lady; thirdly, they have verified unjust things; and to conclude, they are lying knaves." },
    { r = {"DON PEDRO"}, t = "First, I ask thee what they have done; thirdly, I ask thee what’s their offence; sixth and lastly, why they are committed; and, to conclude, what you lay to their charge?" },
    { r = {"CLAUDIO"}, t = "Rightly reasoned, and in his own division; and, by my troth, there’s one meaning well suited." },
    { r = {"DON PEDRO"}, t = "Who have you offended, masters, that you are thus bound to your answer?" },
    { r = {"DON PEDRO"}, t = "This learned constable is too cunning to be understood." },
    { r = {"DON PEDRO"}, t = "What’s your offence?" },
    { r = {"BORACHIO"}, t = "Sweet Prince, let me go no farther to mine answer: do you hear me, and let this Count kill me." },
    { r = {"BORACHIO"}, t = "I have deceived even your very eyes: what your wisdoms could not discover, these shallow fools have brought to light; who, in the night overheard me confessing to this man how Don John your brother incensed me to slander the Lady Hero;" },
    { r = {"BORACHIO"}, t = "how you were brought into the orchard and saw me court Margaret in Hero’s garments; how you disgraced her, when you should marry her." },
    { r = {"BORACHIO"}, t = "My villainy they have upon record; which I had rather seal with my death than repeat over to my shame." },
    { r = {"BORACHIO"}, t = "The lady is dead upon mine and my master’s false accusation; and, briefly, I desire nothing but the reward of a villain." },
    { r = {"DON PEDRO"}, t = "Runs not this speech like iron through your blood?" },
    { r = {"CLAUDIO"}, t = "I have drunk poison whiles he utter’d it." },
    { r = {"DON PEDRO"}, t = "But did my brother set thee on to this?" },
    { r = {"BORACHIO"}, t = "Yea; and paid me richly for the practice of it." },
    { r = {"DON PEDRO"}, t = "He is compos’d and fram’d of treachery:" },
    { r = {"DON PEDRO"}, t = "And fled he is upon this villainy." },
    { r = {"CLAUDIO"}, t = "Sweet Hero! now thy image doth appear" },
    { r = {"CLAUDIO"}, t = "In the rare semblance that I lov’d it first." },
    { r = {"DOGBERRY"}, t = "Come, bring away the plaintiffs: by this time our sexton hath reformed Signior Leonato of the matter." },
    { r = {"DOGBERRY"}, t = "And masters, do not forget to specify, when time and place shall serve, that I am an ass." },
    { r = {"VERGES"}, t = "Here, here comes Master Signior Leonato, and the sexton too." },
    { d = "Re-enter Leonato, Antonio and the Sexton" },
    { r = {"LEONATO"}, t = "Which is the villain? Let me see his eyes," },
    { r = {"LEONATO"}, t = "That, when I note another man like him," },
    { r = {"LEONATO"}, t = "I may avoid him. Which of these is he?" },
    { r = {"BORACHIO"}, t = "If you would know your wronger, look on me." },
    { r = {"LEONATO"}, t = "Art thou the slave that with thy breath hast kill’d" },
    { r = {"LEONATO"}, t = "Mine innocent child?" },
    { r = {"BORACHIO"}, t = "Yea, even I alone." },
    { r = {"LEONATO"}, t = "No, not so, villain; thou beliest thyself:" },
    { r = {"LEONATO"}, t = "Here stand a pair of honourable men;" },
    { r = {"LEONATO"}, t = "A third is fled, that had a hand in it." },
    { r = {"LEONATO"}, t = "I thank you, princes, for my daughter’s death:" },
    { r = {"LEONATO"}, t = "Record it with your high and worthy deeds." },
    { r = {"LEONATO"}, t = "’Twas bravely done, if you bethink you of it." },
    { r = {"CLAUDIO"}, t = "I know not how to pray your patience;" },
    { r = {"CLAUDIO"}, t = "Yet I must speak. Choose your revenge yourself;" },
    { r = {"CLAUDIO"}, t = "Impose me to what penance your invention" },
    { r = {"CLAUDIO"}, t = "Can lay upon my sin: yet sinn’d I not" },
    { r = {"CLAUDIO"}, t = "But in mistaking." },
    { r = {"DON PEDRO"}, t = "By my soul, nor I:" },
    { r = {"DON PEDRO"}, t = "And yet, to satisfy this good old man," },
    { r = {"DON PEDRO"}, t = "I would bend under any heavy weight" },
    { r = {"DON PEDRO"}, t = "That he’ll enjoin me to." },
    { r = {"LEONATO"}, t = "I cannot bid you bid my daughter live;" },
    { r = {"LEONATO"}, t = "That were impossible; but, I pray you both," },
    { r = {"LEONATO"}, t = "Possess the people in Messina here" },
    { r = {"LEONATO"}, t = "How innocent she died; and if your love" },
    { r = {"LEONATO"}, t = "Can labour aught in sad invention," },
    { r = {"LEONATO"}, t = "Hang her an epitaph upon her tomb," },
    { r = {"LEONATO"}, t = "And sing it to her bones: sing it tonight." },
    { r = {"LEONATO"}, t = "Tomorrow morning come you to my house," },
    { r = {"LEONATO"}, t = "And since you could not be my son-in-law," },
    { r = {"LEONATO"}, t = "Be yet my nephew. My brother hath a daughter," },
    { r = {"LEONATO"}, t = "Almost the copy of my child that’s dead," },
    { r = {"LEONATO"}, t = "And she alone is heir to both of us:" },
    { r = {"LEONATO"}, t = "Give her the right you should have given her cousin," },
    { r = {"LEONATO"}, t = "And so dies my revenge." },
    { r = {"CLAUDIO"}, t = "O noble sir," },
    { r = {"CLAUDIO"}, t = "Your over-kindness doth wring tears from me!" },
    { r = {"CLAUDIO"}, t = "I do embrace your offer; and dispose" },
    { r = {"CLAUDIO"}, t = "For henceforth of poor Claudio." },
    { r = {"LEONATO"}, t = "Tomorrow then I will expect your coming;" },
    { r = {"LEONATO"}, t = "Tonight I take my leave. This naughty man" },
    { r = {"LEONATO"}, t = "Shall face to face be brought to Margaret," },
    { r = {"LEONATO"}, t = "Who, I believe, was pack’d in all this wrong," },
    { r = {"LEONATO"}, t = "Hir’d to it by your brother." },
    { r = {"BORACHIO"}, t = "No, by my soul she was not;" },
    { r = {"BORACHIO"}, t = "Nor knew not what she did when she spoke to me;" },
    { r = {"BORACHIO"}, t = "But always hath been just and virtuous" },
    { r = {"BORACHIO"}, t = "In anything that I do know by her." },
    { r = {"DOGBERRY"}, t = "Moreover, sir,—which, indeed, is not under white and black,— this plaintiff here, the offender, did call me ass: I beseech you, let it be remembered in his punishment." },
    { r = {"DOGBERRY"}, t = "And also, the watch heard them talk of one Deformed:" },
    { r = {"DOGBERRY"}, t = "they say he wears a key in his ear and a lock hanging by it, and borrows money in God’s name, the which he hath used so long and never paid, that now men grow hard-hearted, and will lend nothing for God’s sake." },
    { r = {"DOGBERRY"}, t = "Pray you, examine him upon that point." },
    { r = {"LEONATO"}, t = "I thank thee for thy care and honest pains." },
    { r = {"DOGBERRY"}, t = "Your worship speaks like a most thankful and reverent youth, and I praise God for you." },
    { r = {"LEONATO"}, t = "There’s for thy pains." },
    { r = {"DOGBERRY"}, t = "God save the foundation!" },
    { r = {"LEONATO"}, t = "Go, I discharge thee of thy prisoner, and I thank thee." },
    { r = {"DOGBERRY"}, t = "I leave an arrant knave with your worship; which I beseech your worship to correct yourself, for the example of others." },
    { r = {"DOGBERRY"}, t = "God keep your worship!" },
    { r = {"DOGBERRY"}, t = "I wish your worship well; God restore you to health!" },
    { r = {"DOGBERRY"}, t = "I humbly give you leave to depart, and if a merry meeting may be wished, God prohibit it!" },
    { r = {"DOGBERRY"}, t = "Come, neighbour." },
    { d = "Exeunt Dogberry and Verges" },
    { r = {"LEONATO"}, t = "Until tomorrow morning, lords, farewell." },
    { r = {"ANTONIO"}, t = "Farewell, my lords: we look for you tomorrow." },
    { r = {"DON PEDRO"}, t = "We will not fail." },
    { r = {"CLAUDIO"}, t = "Tonight I’ll mourn with Hero." },
    { d = "Exeunt Don Pedro and Claudio" },
    { r = {"LEONATO"}, t = "Bring you these fellows on. We’ll talk with", d = "To the Watch" },
    { r = {"LEONATO"}, t = "Margaret," },
    { r = {"LEONATO"}, t = "How her acquaintance grew with this lewd fellow." },
    { d = "Exeunt" },
    { d = "Act 5, Scene 2. Leonato’s Garden.", h = true },
    { d = "Enter Benedick and Margaret, meeting" },
    { r = {"BENEDICK"}, t = "Pray thee, sweet Mistress Margaret, deserve well at my hands by helping me to the speech of Beatrice." },
    { r = {"MARGARET"}, t = "Will you then write me a sonnet in praise of my beauty?" },
    { r = {"BENEDICK"}, t = "In so high a style, Margaret, that no man living shall come over it; for, in most comely truth, thou deservest it." },
    { r = {"MARGARET"}, t = "To have no man come over me! why, shall I always keep below stairs?" },
    { r = {"BENEDICK"}, t = "Thy wit is as quick as the greyhound’s mouth; it catches." },
    { r = {"MARGARET"}, t = "And yours as blunt as the fencer’s foils, which hit, but hurt not." },
    { r = {"BENEDICK"}, t = "A most manly wit, Margaret; it will not hurt a woman: and so, I pray thee, call Beatrice." },
    { r = {"BENEDICK"}, t = "I give thee the bucklers." },
    { r = {"MARGARET"}, t = "Give us the swords, we have bucklers of our own." },
    { r = {"BENEDICK"}, t = "If you use them, Margaret, you must put in the pikes with a vice; and they are dangerous weapons for maids." },
    { r = {"MARGARET"}, t = "Well, I will call Beatrice to you, who I think hath legs." },
    { r = {"BENEDICK"}, t = "And therefore will come." },
    { d = "Exit Margaret" },
    { r = {"BENEDICK"}, t = "The god of love," },
    { r = {"BENEDICK"}, t = "That sits above," },
    { r = {"BENEDICK"}, t = "And knows me, and knows me," },
    { r = {"BENEDICK"}, t = "How pitiful I deserve," },
    { r = {"BENEDICK"}, t = "I mean, in singing: but in loving, Leander the good swimmer, Troilus the first employer of panders, and a whole book full of these quondam carpet-mongers, whose names yet run smoothly in the even road of a blank verse, why," },
    { r = {"BENEDICK"}, t = "they were never so truly turned over and over as my poor self in love." },
    { r = {"BENEDICK"}, t = "Marry, I cannot show it in rime; I have tried: I can find out no rime to ‘lady’ but ‘baby’, an innocent rime; for ‘scorn,’ ‘horn’, a hard rime; for ‘school’, ‘fool’, a babbling rime; very ominous endings:" },
    { r = {"BENEDICK"}, t = "no, I was not born under a riming planet, nor I cannot woo in festival terms." },
    { d = "Enter Beatrice" },
    { r = {"BENEDICK"}, t = "Sweet Beatrice, wouldst thou come when I called thee?" },
    { r = {"BEATRICE"}, t = "Yea, signior; and depart when you bid me." },
    { r = {"BENEDICK"}, t = "O, stay but till then!" },
    { r = {"BEATRICE"}, t = "‘Then’ is spoken; fare you well now: and yet, ere I go, let me go with that I came for; which is, with knowing what hath passed between you and Claudio." },
    { r = {"BENEDICK"}, t = "Only foul words; and thereupon I will kiss thee." },
    { r = {"BEATRICE"}, t = "Foul words is but foul wind, and foul wind is but foul breath, and foul breath is noisome; therefore I will depart unkissed." },
    { r = {"BENEDICK"}, t = "Thou hast frighted the word out of his right sense, so forcible is thy wit." },
    { r = {"BENEDICK"}, t = "But I must tell thee plainly, Claudio undergoes my challenge, and either I must shortly hear from him, or I will subscribe him a coward." },
    { r = {"BENEDICK"}, t = "And, I pray thee now, tell me, for which of my bad parts didst thou first fall in love with me?" },
    { r = {"BEATRICE"}, t = "For them all together; which maintained so politic a state of evil that they will not admit any good part to intermingle with them." },
    { r = {"BEATRICE"}, t = "But for which of my good parts did you first suffer love for me?" },
    { r = {"BENEDICK"}, t = "‘Suffer love,’ a good epithet!" },
    { r = {"BENEDICK"}, t = "I do suffer love indeed, for I love thee against my will." },
    { r = {"BEATRICE"}, t = "In spite of your heart, I think." },
    { r = {"BEATRICE"}, t = "Alas, poor heart!" },
    { r = {"BEATRICE"}, t = "If you spite it for my sake, I will spite it for yours; for I will never love that which my friend hates." },
    { r = {"BENEDICK"}, t = "Thou and I are too wise to woo peaceably." },
    { r = {"BEATRICE"}, t = "It appears not in this confession: there’s not one wise man among twenty that will praise himself." },
    { r = {"BENEDICK"}, t = "An old, an old instance, Beatrice, that lived in the time of good neighbours." },
    { r = {"BENEDICK"}, t = "If a man do not erect in this age his own tomb ere he dies, he shall live no longer in monument than the bell rings and the widow weeps." },
    { r = {"BEATRICE"}, t = "And how long is that think you?" },
    { r = {"BENEDICK"}, t = "Question: why, an hour in clamour and a quarter in rheum: therefore is it most expedient for the wise,—if Don Worm, his conscience, find no impediment to the contrary,—to be the trumpet of his own virtues, as I am to myself." },
    { r = {"BENEDICK"}, t = "So much for praising myself, who, I myself will bear witness, is praiseworthy." },
    { r = {"BENEDICK"}, t = "And now tell me, how doth your cousin?" },
    { r = {"BEATRICE"}, t = "Very ill." },
    { r = {"BENEDICK"}, t = "And how do you?" },
    { r = {"BEATRICE"}, t = "Very ill too." },
    { r = {"BENEDICK"}, t = "Serve God, love me, and mend." },
    { r = {"BENEDICK"}, t = "There will I leave you too, for here comes one in haste." },
    { d = "Enter Ursula" },
    { r = {"URSULA"}, t = "Madam, you must come to your uncle." },
    { r = {"URSULA"}, t = "Yonder’s old coil at home: it is proved, my Lady Hero hath been falsely accused, the Prince and Claudio mightily abused; and Don John is the author of all, who is fled and gone." },
    { r = {"URSULA"}, t = "Will you come presently?" },
    { r = {"BEATRICE"}, t = "Will you go hear this news, signior?" },
    { r = {"BENEDICK"}, t = "I will live in thy heart, die in thy lap, and be buried in thy eyes; and moreover I will go with thee to thy uncle’s." },
    { d = "Exeunt" },
    { d = "Act 5, Scene 3. The Inside of a Church.", h = true },
    { d = "Enter Don Pedro, Claudio and Attendants, with music and tapers" },
    { r = {"CLAUDIO"}, t = "Is this the monument of Leonato?" },
    { r = {"A LORD"}, t = "It is, my lord." },
    { d = "Reads from a scroll" },
    { r = {"CLAUDIO"}, t = "Epitaph." },
    { r = {"CLAUDIO"}, t = "Done to death by slanderous tongues" },
    { r = {"CLAUDIO"}, t = "Was the Hero that here lies:" },
    { r = {"CLAUDIO"}, t = "Death, in guerdon of her wrongs," },
    { r = {"CLAUDIO"}, t = "Gives her fame which never dies." },
    { r = {"CLAUDIO"}, t = "So the life that died with shame" },
    { r = {"CLAUDIO"}, t = "Lives in death with glorious fame." },
    { r = {"CLAUDIO"}, t = "Hang thou there upon the tomb," },
    { r = {"CLAUDIO"}, t = "Praising her when I am dumb." },
    { r = {"CLAUDIO"}, t = "Now, music, sound, and sing your solemn hymn." },
    { r = {"CLAUDIO"}, t = "Song." },
    { r = {"CLAUDIO"}, t = "Pardon, goddess of the night," },
    { r = {"CLAUDIO"}, t = "Those that slew thy virgin knight;" },
    { r = {"CLAUDIO"}, t = "For the which, with songs of woe," },
    { r = {"CLAUDIO"}, t = "Round about her tomb they go." },
    { r = {"CLAUDIO"}, t = "Midnight, assist our moan;" },
    { r = {"CLAUDIO"}, t = "Help us to sigh and groan," },
    { r = {"CLAUDIO"}, t = "Heavily, heavily:" },
    { r = {"CLAUDIO"}, t = "Graves, yawn and yield your dead," },
    { r = {"CLAUDIO"}, t = "Till death be uttered," },
    { r = {"CLAUDIO"}, t = "Heavily, heavily." },
    { r = {"CLAUDIO"}, t = "Now, unto thy bones good night!" },
    { r = {"CLAUDIO"}, t = "Yearly will I do this rite." },
    { r = {"DON PEDRO"}, t = "Good morrow, masters: put your torches out." },
    { r = {"DON PEDRO"}, t = "The wolves have prey’d; and look, the gentle day," },
    { r = {"DON PEDRO"}, t = "Before the wheels of Phoebus, round about" },
    { r = {"DON PEDRO"}, t = "Dapples the drowsy East with spots of grey." },
    { r = {"DON PEDRO"}, t = "Thanks to you all, and leave us: fare you well." },
    { r = {"CLAUDIO"}, t = "Good morrow, masters: each his several way." },
    { r = {"DON PEDRO"}, t = "Come, let us hence, and put on other weeds;" },
    { r = {"DON PEDRO"}, t = "And then to Leonato’s we will go." },
    { r = {"CLAUDIO"}, t = "And Hymen now with luckier issue speed’s," },
    { r = {"CLAUDIO"}, t = "Than this for whom we rend’red up this woe!" },
    { d = "Exeunt" },
    { d = "Act 5, Scene 4. A Room in Leonato’s House.", h = true },
    { d = "Enter Leonato, Antonio, Benedick, Beatrice, Margaret, Ursula, Friar Francis and Hero" },
    { r = {"FRIAR FRANCIS"}, t = "Did I not tell you she was innocent?" },
    { r = {"LEONATO"}, t = "So are the Prince and Claudio, who accus’d her" },
    { r = {"LEONATO"}, t = "Upon the error that you heard debated:" },
    { r = {"LEONATO"}, t = "But Margaret was in some fault for this," },
    { r = {"LEONATO"}, t = "Although against her will, as it appears" },
    { r = {"LEONATO"}, t = "In the true course of all the question." },
    { r = {"ANTONIO"}, t = "Well, I am glad that all things sort so well." },
    { r = {"BENEDICK"}, t = "And so am I, being else by faith enforc’d" },
    { r = {"BENEDICK"}, t = "To call young Claudio to a reckoning for it." },
    { r = {"LEONATO"}, t = "Well, daughter, and you gentlewomen all," },
    { r = {"LEONATO"}, t = "Withdraw into a chamber by yourselves," },
    { r = {"LEONATO"}, t = "And when I send for you, come hither mask’d:" },
    { r = {"LEONATO"}, t = "The Prince and Claudio promis’d by this hour" },
    { r = {"LEONATO"}, t = "To visit me." },
    { d = "Exeunt Ladies" },
    { r = {"LEONATO"}, t = "You know your office, brother;" },
    { r = {"LEONATO"}, t = "You must be father to your brother’s daughter," },
    { r = {"LEONATO"}, t = "And give her to young Claudio." },
    { r = {"ANTONIO"}, t = "Which I will do with confirm’d countenance." },
    { r = {"BENEDICK"}, t = "Friar, I must entreat your pains, I think." },
    { r = {"FRIAR FRANCIS"}, t = "To do what, signior?" },
    { r = {"BENEDICK"}, t = "To bind me, or undo me; one of them." },
    { r = {"BENEDICK"}, t = "Signior Leonato, truth it is, good signior," },
    { r = {"BENEDICK"}, t = "Your niece regards me with an eye of favour." },
    { r = {"LEONATO"}, t = "That eye my daughter lent her. ’Tis most true." },
    { r = {"BENEDICK"}, t = "And I do with an eye of love requite her." },
    { r = {"LEONATO"}, t = "The sight whereof I think, you had from me," },
    { r = {"LEONATO"}, t = "From Claudio, and the Prince. But what’s your will?" },
    { r = {"BENEDICK"}, t = "Your answer, sir, is enigmatical:" },
    { r = {"BENEDICK"}, t = "But, for my will, my will is your good will" },
    { r = {"BENEDICK"}, t = "May stand with ours, this day to be conjoin’d" },
    { r = {"BENEDICK"}, t = "In the state of honourable marriage:" },
    { r = {"BENEDICK"}, t = "In which, good friar, I shall desire your help." },
    { r = {"LEONATO"}, t = "My heart is with your liking." },
    { r = {"FRIAR FRANCIS"}, t = "And my help. Here comes the Prince and Claudio." },
    { d = "Enter Don Pedro and Claudio, with Attendants" },
    { r = {"DON PEDRO"}, t = "Good morrow to this fair assembly." },
    { r = {"LEONATO"}, t = "Good morrow, Prince; good morrow, Claudio:" },
    { r = {"LEONATO"}, t = "We here attend you. Are you yet determin’d" },
    { r = {"LEONATO"}, t = "Today to marry with my brother’s daughter?" },
    { r = {"CLAUDIO"}, t = "I’ll hold my mind, were she an Ethiope." },
    { r = {"LEONATO"}, t = "Call her forth, brother: here’s the friar ready." },
    { d = "Exit Antonio" },
    { r = {"DON PEDRO"}, t = "Good morrow, Benedick. Why, what’s the matter," },
    { r = {"DON PEDRO"}, t = "That you have such a February face," },
    { r = {"DON PEDRO"}, t = "So full of frost, of storm and cloudiness?" },
    { r = {"CLAUDIO"}, t = "I think he thinks upon the savage bull." },
    { r = {"CLAUDIO"}, t = "Tush! fear not, man, we’ll tip thy horns with gold," },
    { r = {"CLAUDIO"}, t = "And all Europa shall rejoice at thee," },
    { r = {"CLAUDIO"}, t = "As once Europa did at lusty Jove," },
    { r = {"CLAUDIO"}, t = "When he would play the noble beast in love." },
    { r = {"BENEDICK"}, t = "Bull Jove, sir, had an amiable low:" },
    { r = {"BENEDICK"}, t = "And some such strange bull leap’d your father’s cow," },
    { r = {"BENEDICK"}, t = "And got a calf in that same noble feat," },
    { r = {"BENEDICK"}, t = "Much like to you, for you have just his bleat." },
    { r = {"CLAUDIO"}, t = "For this I owe you: here comes other reckonings." },
    { d = "Re-enter Antonio, with the ladies masked" },
    { r = {"CLAUDIO"}, t = "Which is the lady I must seize upon?" },
    { r = {"ANTONIO"}, t = "This same is she, and I do give you her." },
    { r = {"CLAUDIO"}, t = "Why then, she’s mine. Sweet, let me see your face." },
    { r = {"LEONATO"}, t = "No, that you shall not, till you take her hand" },
    { r = {"LEONATO"}, t = "Before this friar, and swear to marry her." },
    { r = {"CLAUDIO"}, t = "Give me your hand: before this holy friar," },
    { r = {"CLAUDIO"}, t = "I am your husband, if you like of me." },
    { r = {"HERO"}, t = "And when I liv’d, I was your other wife:" },
    { r = {"HERO"}, t = "And when you lov’d, you were my other husband.", d = "Unmasking" },
    { r = {"CLAUDIO"}, t = "Another Hero!" },
    { r = {"HERO"}, t = "Nothing certainer:" },
    { r = {"HERO"}, t = "One Hero died defil’d, but I do live," },
    { r = {"HERO"}, t = "And surely as I live, I am a maid." },
    { r = {"DON PEDRO"}, t = "The former Hero! Hero that is dead!" },
    { r = {"LEONATO"}, t = "She died, my lord, but whiles her slander liv’d." },
    { r = {"FRIAR FRANCIS"}, t = "All this amazement can I qualify:" },
    { r = {"FRIAR FRANCIS"}, t = "When after that the holy rites are ended," },
    { r = {"FRIAR FRANCIS"}, t = "I’ll tell you largely of fair Hero’s death:" },
    { r = {"FRIAR FRANCIS"}, t = "Meantime, let wonder seem familiar," },
    { r = {"FRIAR FRANCIS"}, t = "And to the chapel let us presently." },
    { r = {"BENEDICK"}, t = "Soft and fair, friar. Which is Beatrice?" },
    { r = {"BEATRICE"}, t = "I answer to that name. What is your will?", d = "Unmasking" },
    { r = {"BENEDICK"}, t = "Do not you love me?" },
    { r = {"BEATRICE"}, t = "Why, no; no more than reason." },
    { r = {"BENEDICK"}, t = "Why, then, your uncle and the Prince and Claudio" },
    { r = {"BENEDICK"}, t = "Have been deceived; for they swore you did." },
    { r = {"BEATRICE"}, t = "Do not you love me?" },
    { r = {"BENEDICK"}, t = "Troth, no; no more than reason." },
    { r = {"BEATRICE"}, t = "Why, then my cousin, Margaret, and Ursula," },
    { r = {"BEATRICE"}, t = "Are much deceiv’d; for they did swear you did." },
    { r = {"BENEDICK"}, t = "They swore that you were almost sick for me." },
    { r = {"BEATRICE"}, t = "They swore that you were well-nigh dead for me." },
    { r = {"BENEDICK"}, t = "’Tis no such matter. Then you do not love me?" },
    { r = {"BEATRICE"}, t = "No, truly, but in friendly recompense." },
    { r = {"LEONATO"}, t = "Come, cousin, I am sure you love the gentleman." },
    { r = {"CLAUDIO"}, t = "And I’ll be sworn upon ’t that he loves her;" },
    { r = {"CLAUDIO"}, t = "For here’s a paper written in his hand," },
    { r = {"CLAUDIO"}, t = "A halting sonnet of his own pure brain," },
    { r = {"CLAUDIO"}, t = "Fashion’d to Beatrice." },
    { r = {"HERO"}, t = "And here’s another," },
    { r = {"HERO"}, t = "Writ in my cousin’s hand, stolen from her pocket," },
    { r = {"HERO"}, t = "Containing her affection unto Benedick." },
    { r = {"BENEDICK"}, t = "A miracle! here’s our own hands against our hearts. Come," },
    { r = {"BENEDICK"}, t = "I will have thee; but, by this light, I take thee for pity." },
    { r = {"BEATRICE"}, t = "I would not deny you; but, by this good day, I yield upon great persuasion, and partly to save your life, for I was told you were in a consumption." },
    { r = {"BENEDICK"}, t = "Peace! I will stop your mouth." },
    { r = {"BENEDICK"}, d = "Kisses her", e = "/kiss", at = "BEATRICE" },
    { r = {"DON PEDRO"}, t = "How dost thou, Benedick, the married man?" },
    { r = {"BENEDICK"}, t = "I’ll tell thee what, Prince; a college of witcrackers cannot flout me out of my humour." },
    { r = {"BENEDICK"}, t = "Dost thou think I care for a satire or an epigram?" },
    { r = {"BENEDICK"}, t = "No; if man will be beaten with brains, a’ shall wear nothing handsome about him." },
    { r = {"BENEDICK"}, t = "In brief, since I do purpose to marry, I will think nothing to any purpose that the world can say against it; and therefore never flout at me for what I have said against it, for man is a giddy thing, and this is my conclusion." },
    { r = {"BENEDICK"}, t = "For thy part, Claudio, I did think to have beaten thee; but, in that thou art like to be my kinsman, live unbruised, and love my cousin." },
    { r = {"CLAUDIO"}, t = "I had well hoped thou wouldst have denied Beatrice, that I might have cudgelled thee out of thy single life, to make thee a double-dealer; which, out of question, thou wilt be, if my cousin do not look exceeding narrowly to thee." },
    { r = {"BENEDICK"}, t = "Come, come, we are friends." },
    { r = {"BENEDICK"}, t = "Let’s have a dance ere we are married, that we may lighten our own hearts and our wives’ heels." },
    { r = {"LEONATO"}, t = "We’ll have dancing afterward." },
    { r = {"BENEDICK"}, t = "First, of my word; therefore play, music!" },
    { r = {"BENEDICK"}, t = "Prince, thou art sad; get thee a wife, get thee a wife: there is no staff more reverent than one tipped with horn." },
    { d = "Enter Messenger" },
    { r = {"MESSENGER"}, t = "My lord, your brother John is ta’en in flight," },
    { r = {"MESSENGER"}, t = "And brought with armed men back to Messina." },
    { r = {"BENEDICK"}, t = "Think not on him till tomorrow: I’ll devise thee brave punishments for him." },
    { r = {"BENEDICK"}, t = "Strike up, pipers!" },
    { d = "Dance. Exeunt" },
  },
}
